insert into learn_modules (
  slug, level_slug, position, title, number, core_question, intro_markdown,
  est_minutes, is_mandatory
) values (
  'who-needs-organs', 'beginner', 0, 'Who Needs Organs?', 1,
  'Why do people need donated organs and tissues?', 'Transplantation is easy to think about in the abstract. It is much harder to ignore once you know who is actually waiting.

This module puts people, not procedures, at the centre. Before we talk about how donation works, or why it so often does not, it is worth understanding what is at stake for someone in end-stage organ failure — and what a transplant actually gives back.', 8,
  true
) on conflict (slug) do update set
  level_slug = excluded.level_slug, position = excluded.position,
  title = excluded.title, number = excluded.number,
  core_question = excluded.core_question, intro_markdown = excluded.intro_markdown,
  est_minutes = excluded.est_minutes, is_mandatory = excluded.is_mandatory,
  updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'intro', 'who-needs-organs', 0, 'Why this matters', 'INTRO',
  'Most conversations about organ donation start in the wrong place — with death. This one starts with the people who are still alive, and waiting.

Organ and tissue transplantation is needed by patients with **end-stage organ failure**, to save their lives or significantly improve them. When an organ fails completely there is often no way to repair it. Treatment can buy time, sometimes a great deal of it, but for some conditions a transplant is the only remaining option.

**Thousands of South Africans are on waiting lists** for lifesaving organ and tissue transplants. Published totals vary between sources, which is why this course says *thousands* rather than a number it cannot stand behind.

The rest of this course is about why so few of them receive one. This module is about who they are.', NULL,
  NULL
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'explore-organs-and-tissues', 'who-needs-organs', 1, 'What can be donated, and who needs it', 'PRIMARY',
  NULL, 'OrganExplorer',
  '{"intro":"Select any organ or tissue to see why someone might need it, and what a transplant gives them back. Notice how wide the list is — donation is not only about hearts.","groups":[{"id":"solid-organs","label":"Solid organs","caption":"Recovered and transplanted within hours, and only from a clinical setting. These are the donations most people picture.","items":[{"id":"kidney","name":"Kidneys","category":"Solid organ","whyNeeded":"End-stage renal disease — chronic kidney disease stage 5, where the kidneys can no longer filter the blood well enough to sustain life.","restores":"Freedom from dialysis, and protection from early death. This is the most commonly transplanted organ in South Africa: 2 416 kidney transplants between 2010 and 2019.","note":"A kidney can also come from a living donor."},{"id":"liver","name":"Liver","category":"Solid organ","whyNeeded":"Hepatocellular carcinoma, decompensated cirrhosis, or fulminant hepatic failure — liver disease that has passed the point of recovery.","restores":"Life itself. 593 South African patients were helped with liver transplants between 2010 and 2019.","note":"A segment of liver can also come from a living donor."},{"id":"heart","name":"Heart","category":"Solid organ","whyNeeded":"End-stage heart failure — typically NYHA class IV, with an ejection fraction below 20%. The heart can no longer pump enough blood to sustain ordinary activity.","restores":"Years of active living. 292 hearts were transplanted in South Africa between 2010 and 2019."},{"id":"lungs","name":"Lungs","category":"Solid organ","whyNeeded":"Advanced lung disease such as COPD or cystic fibrosis, where the risk of death exceeds 50% over the next two years.","restores":"The ability to breathe unaided. Lung transplantation remains rare here: 101 lungs transplanted between 2010 and 2019."},{"id":"pancreas","name":"Pancreas","category":"Solid organ","whyNeeded":"Diabetes severe enough that insulin can no longer manage it well, often alongside kidney failure.","restores":"An end to insulin dependency."}]},{"id":"tissue","label":"Tissue","caption":"Often left out of public conversation, and by volume the largest part of what donation achieves. In excess of 150 000 South Africans received tissue transplants between 2010 and 2019.","items":[{"id":"corneas","name":"Corneas","category":"Tissue","whyNeeded":"Corneal damage or disease causing blindness. Note that poor eyesight or cataracts in the donor do not disqualify a cornea.","restores":"Sight. 1 911 patients had their sight restored by corneal transplants between 2010 and 2019.","note":"Cornea donors are generally between 6 and 65 years old."},{"id":"bone-ligaments","name":"Bone and ligaments","category":"Tissue","whyNeeded":"Bone loss or ligament damage from injury, disease or surgery.","restores":"Mobility, and relief from pain.","note":"Bone donors are typically healthy individuals between 16 and 80, without infectious disease or cancer."},{"id":"skin","name":"Skin","category":"Tissue","whyNeeded":"Severe burn injury.","restores":"Survival. Donated skin is what keeps a badly burned patient alive.","note":"Skin donors are typically healthy individuals between 16 and 80, without infectious disease or cancer."},{"id":"heart-valves","name":"Heart valves","category":"Tissue","whyNeeded":"Valve disease, including in children born with heart defects.","restores":"Heart function.","note":"Heart valve donors are eligible from 6 months up to 55 years of age."}]}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'takeaways', 'who-needs-organs', 2, 'Key takeaways', 'TAKEAWAYS',
  NULL, 'TakeawayList',
  '{"takeaways":[{"id":"t1","text":"Transplantation is not an enhancement. For people in end-stage organ failure it saves or significantly improves life, and for some conditions it is the only remaining option."},{"id":"t2","text":"Thousands of South Africans are on waiting lists for organ and tissue transplants. Published totals differ between sources, so quote the scale rather than a figure."},{"id":"t3","text":"One donor can save seven lives through organ donation, and improve up to fifty more through tissue and corneas — the published South African figures, and where Save7''s name comes from.","detail":"This is where Save7''s name comes from. The tissue figure is the part most people have never heard."},{"id":"t4","text":"Donation is far wider than hearts: kidneys, liver, heart, lungs and pancreas, plus corneas, bone, ligaments, skin and heart valves."},{"id":"t5","text":"By volume, tissue is the largest part of what donation achieves — in excess of 150 000 South Africans received tissue transplants between 2010 and 2019."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

