insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'study-guide', 'who-needs-organs', 4, 'Study guide', 'STUDY_GUIDE',
  NULL, NULL,
  '{"summary":"Objective 1 of the Save7 study guide: understand who needs organs.","sections":[{"id":"s1","heading":"End-stage organ failure","body":"Organ and tissue transplantation is required by patients with end-stage organ failure, to save or significantly improve their lives. Thousands of patients are on national waiting lists for lifesaving organ and tissue transplants; published totals vary between sources, so the scale is what to quote.\n\nRecipients include people needing hearts for years of active living, lungs to allow unaided breathing, and kidneys to save them from dialysis or early death. Patients with liver failure require transplants to restore life, and those needing a pancreas can eliminate insulin dependency."},{"id":"s2","heading":"Specific indications","bullets":["Kidney — end-stage renal disease (CKD 5)","Liver — hepatocellular carcinoma, decompensated cirrhosis, fulminant hepatic failure","Heart — end-stage heart failure (NYHA class IV) with an ejection fraction below 20%","Lung — advanced lung disease such as COPD or cystic fibrosis, with a risk of death exceeding 50% over the next two years","Pancreas — to eliminate insulin dependency"]},{"id":"s3","heading":"Tissue transplantation","body":"Tissue transplants restore sight (corneas), increase mobility and reduce pain (bone and ligaments), save lives after severe burn injury (skin), and improve heart function (heart valves)."},{"id":"s4","heading":"The impact of one donor","body":"One donor can save seven lives through organ donation, and improve up to fifty more through tissue donation — the figures the Organ Donor Foundation and ORTIDA both publish, and where Save7''s name comes from. (An earlier version of this page said “65 or more”; that figure could not be sourced, and the published South African number is fifty.)","bullets":["2 416 kidneys transplanted (2010–2019)","593 patients helped with liver transplants (2010–2019)","292 hearts transplanted (2010–2019)","101 lungs transplanted (2010–2019)","1 911 patients had sight restored by corneal transplants (2010–2019)","In excess of 150 000 South Africans received tissue transplants (2010–2019)"],"verifiedAgainst":"Organ Donor Foundation and ORTIDA published figures: one donor can save seven lives and enhance up to fifty more through tissue donation. The 2010–2019 decade totals remain as published by the ODF and are date-stamped; the ODF no longer hosts them, so Save7 should refresh them from SATS when current figures are available."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

