insert into learn_modules (
  slug, level_slug, position, title, number, core_question, intro_markdown,
  est_minutes, is_mandatory
) values (
  'why-are-we-losing-organs', 'beginner', 1, 'Why Are We Losing Organs?', 2,
  'If so many people need organs, why aren''t more organs reaching them?', 'This is the most important module in the course.

South Africa does not have an organ shortage because donation is impossible. It has a shortage because the pathway from a potential donor to a transplanted recipient has many points at which it can quietly break — and most of those points are human, not medical.

Once you can see where donations are lost, you understand exactly why the conversation Save7 asks you to start actually matters.', 12,
  true
) on conflict (slug) do update set
  level_slug = excluded.level_slug, position = excluded.position,
  title = excluded.title, number = excluded.number,
  core_question = excluded.core_question, intro_markdown = excluded.intro_markdown,
  est_minutes = excluded.est_minutes, is_mandatory = excluded.is_mandatory,
  updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'intro', 'why-are-we-losing-organs', 0, 'Why this matters', 'INTRO',
  'It is tempting to explain the shortage with a single cause. The reality is a chain, and a chain fails at whichever link gives way first.

A potential donor has to be identified. They have to be referred. Death has to be determined. A family has to be approached and asked to consent. Only then can recovery and transplantation follow.

One fact sits underneath all of it, and it is the single most useful thing you can carry out of this module:

> **Consent from next of kin is always required for donation to proceed.**

That is why registering is not enough on its own. If your family has never heard you say what you want, they are being asked to guess — at the worst moment of their lives.', NULL,
  NULL
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'where-donations-are-lost', 'why-are-we-losing-organs', 1, 'Where donations are lost', 'PRIMARY',
  NULL, 'PathwayJourney',
  '{"intro":"Walk the pathway a potential donation follows. At each step, open the loss points to see how a donation can be lost there.","showLossPoints":true,"steps":[{"id":"potential-donor","label":"Potential donor","summary":"Someone whose circumstances mean donation may become possible.","detail":"Organ donation can only take place in a clinical setting — most often an intensive care unit, where a patient is on a mechanical ventilator. Tissue donation is broader, and can occur irrespective of the manner of death.","lossPoints":[{"id":"no-awareness","label":"Lack of awareness and ignorance of the process","detail":"If people have never considered donation, their families have nothing to go on when they are asked."},{"id":"never-discussed","label":"Registered donors never told their family","detail":"This is the loss point Save7 exists to address. Consent from next of kin is always required — so a registration nobody knows about cannot be acted on."}]},{"id":"identification","label":"Identification","summary":"A clinical team recognises that donation may be possible.","detail":"Identification and referral are the responsibility of the primary treatment team — the doctors and nurses already caring for the patient — as part of end-of-life care.","lossPoints":[{"id":"not-identified","label":"Potential donors are never identified","detail":"Three triggers should prompt a referral in any ventilated patient: a decision has been made to perform brain death tests; there is a catastrophic brain injury with GCS 3–4 not explained by sedation, after a period of observation; or there is an intention to discuss withdrawal of life-sustaining treatment that is expected to result in circulatory death."}]},{"id":"referral","label":"Referral","summary":"The potential donor is referred to a transplant coordinator.","detail":"There is no legal requirement to refer a potential donor. Referral happens because a clinician chooses to make it happen — which is exactly why awareness among clinical staff matters so much. Early referral lets the coordinator screen the patient, identify when donation is not feasible, and avoid delays for the family.","lossPoints":[{"id":"not-referred","label":"Failure to refer before death, or before treatment is withdrawn","detail":"Once the window closes it cannot be reopened. A referral made too late is the same as no referral at all."}]},{"id":"determination-of-death","label":"Determination of death","summary":"Death is formally determined, according to established criteria.","detail":"Two independent doctors are legally required to certify brain death, and neither may be part of the transplant team. Module 6 covers the process in detail.","lossPoints":[{"id":"brain-death-misunderstood","label":"Brain death is misunderstood","detail":"Families may believe their relative is still alive because a ventilator is providing oxygen and the heart is still beating. If a family believes recovery is possible, no consent conversation can succeed."}]},{"id":"family-conversation","label":"Family conversation","summary":"The family is approached about donation.","detail":"The diagnosis of death and the question of donation are deliberately kept apart. The family is told about the death first, and must understand and accept it, before donation is raised at all — usually by a transplant coordinator rather than the treating doctor. This separation is called decoupling.","lossPoints":[{"id":"fear","label":"Fear-based understandings","detail":"Fear does not respond to information delivered impatiently. It responds to being taken seriously."},{"id":"myths","label":"Myths and misunderstandings within communities","detail":"Covered in the next lesson, with what is actually true."},{"id":"cultural","label":"Cultural and religious barriers","detail":"Donation is possible from all communities and cultures in South Africa. It should never be assumed that because a patient or family comes from a particular ethnic, cultural or spiritual background, a referral should not be made — that assumption removes the family''s choice before they are given it."},{"id":"timing","label":"Being approached at an inappropriate time","detail":"Families who are approached before they have accepted the death, or who are rushed, are far more likely to refuse."}]},{"id":"consent","label":"Consent","summary":"Consent for donation is given or withheld by next of kin.","detail":"Informed consent must be obtained from next of kin — a spouse, parent, child, brother or sister — or from a legal guardian. There is an ethical obligation to give every family the opportunity to make a fully informed decision, whichever way they decide.","lossPoints":[{"id":"family-refusal","label":"Family refusal","detail":"Families often say no because they never received factual information, or because they were asked at the wrong moment. A family that already knows their relative''s wishes is not being asked to guess."},{"id":"rushing","label":"Rushing the decision","detail":"A single-centre study of 107 brain-dead potential donors found that families who took 48 hours or more to decide consented at 73% (11 of 15), compared with 55% (51 of 92) among those who decided sooner. The authors’ own conclusion is the careful one: the delayed group was *not inferior*, not that waiting produces consent. The numbers in that subgroup are small and the setting is not South African — but it is a real argument for continuing to support a family rather than pressing them."}]},{"id":"recovery","label":"Recovery","summary":"Organs and tissues are surgically recovered.","detail":"Recovery is performed in an operating theatre by trained teams, ethically and respectfully. Anaesthesia is given to the deceased to reduce the remaining physiologic response to surgery, and the body is restored to its original state afterwards.","lossPoints":[{"id":"logistics","label":"Logistical and resource constraints","detail":"Theatre availability, staffing and transport all have to align within a narrow window."}]},{"id":"transplantation","label":"Transplantation","summary":"A recipient receives the transplant.","detail":"Long-term outcomes across the whole system improve when there is a larger pool of donors to allocate from — so every donation that is lost affects more than one person.","lossPoints":[]}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'common-myths', 'why-are-we-losing-organs', 2, 'The myths that cost lives', 'PRIMARY',
  NULL, 'MythFlip',
  '{"intro":"These are the beliefs that most often end a donation conversation. Turn each card over. You will meet all of them again in Module 4, where you practise responding.","cards":[{"id":"m1","myth":"Doctors won''t try as hard to save me if I''m a registered organ donor.","fact":"Two independent registered medical doctors are legally required to certify brain death, and neither of them may be part of the transplant team. The people caring for you and the people who would recover organs are deliberately kept separate — that separation is built into the law, not left to good intentions.","whyItPersists":"It taps a real and reasonable fear: that someone else''s interests could outweigh your own while you cannot speak for yourself."},{"id":"m2","myth":"I don''t want doctors cutting me up after I''m dead.","fact":"Recovery is a surgical procedure carried out in an operating theatre with the same care as any other operation, and the body is restored to its original state afterwards. Anaesthesia is given to the deceased to reduce the remaining physiologic response to the surgery.","whyItPersists":"This is rarely a factual objection. It is usually about dignity, and about protecting the body of someone loved."},{"id":"m3","myth":"My religion doesn''t allow organ donation.","fact":"Donation is possible from all communities and cultures in South Africa, and a faith representative or hospital chaplain can be included to support a family during these discussions. What is not appropriate is for anyone else to decide what a person''s faith permits on their behalf — including you.","whyItPersists":"Assumptions about a faith''s position are often inherited rather than checked. The honest response is to help someone find out, not to tell them what their faith says."},{"id":"m4","myth":"I''m too old or too sick to be a donor.","fact":"There is no age restriction for solid organ donation. Donors with conditions such as hypertension, diabetes or HIV may still be eligible if individual organs are assessed as transplantable. Module 8 covers this properly.","whyItPersists":"People rule themselves out privately, and never mention it — so nobody ever gets the chance to correct them."},{"id":"m5","myth":"Brain death isn''t really death — people wake up from comas.","fact":"There is no documented case of a person who met the preconditions and criteria for brain death ever subsequently regaining any brain function. A coma is a different state entirely, and recovery from a coma is possible. Module 6 separates the two carefully.","whyItPersists":"Coma and brain death look similar from a bedside, and are constantly conflated in film and news reporting."},{"id":"m6","myth":"Donation will cost my family money.","fact":"By law, once brain death has been declared and consent obtained, the donor''s medical aid, estate and next of kin are not responsible for any costs related to the donation.","whyItPersists":"Families facing a sudden death are often already frightened about money, and nobody has told them otherwise."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'takeaways', 'why-are-we-losing-organs', 3, 'Key takeaways', 'TAKEAWAYS',
  NULL, 'TakeawayList',
  '{"takeaways":[{"id":"t1","text":"Consent from next of kin is always required. Registering records your wishes; telling your family is what makes them actionable."},{"id":"t2","text":"The shortage is a pathway problem. A donation can be lost at any step between a potential donor and a recipient, and most of those steps are human rather than medical."},{"id":"t3","text":"Families often refuse because they never received factual information, or because they were approached at the wrong moment — not because they are against donation."},{"id":"t4","text":"There is no legal requirement to refer a potential donor. Referral happens because someone chooses to make it happen."},{"id":"t5","text":"Taking longer to decide does not mean refusing. Families who took more than 48 hours consented at a higher rate, not a lower one."},{"id":"t6","text":"Never assume someone''s culture, religion or background means donation shouldn''t be raised. That assumption takes the choice away before it is offered."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

