insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'study-guide', 'why-are-we-losing-organs', 5, 'Study guide', 'STUDY_GUIDE',
  NULL, NULL,
  '{"summary":"Objective 2 of the Save7 study guide: know where and why we are losing organs.","sections":[{"id":"s1","heading":"Where and why organs are lost","bullets":["Lack of awareness and ignorance regarding the donation process","Fear-based understandings, cultural barriers, myths and misunderstandings within communities","Families automatically saying \"no\" because they never received factual information, or were approached at an inappropriate time","Registered donors not sharing their intentions with loved ones — consent from next of kin is always required","Misunderstanding brain death, such as believing a patient is still alive because a ventilator is providing oxygen","Concerns about body disfigurement during recovery surgery, despite the body being restored to its original state afterwards","In the clinical setting, failure to identify and refer a potential donor to a coordinator before death or before treatment is withdrawn"]},{"id":"s2","heading":"Referral triggers","body":"In any mechanically ventilated patient, a referral should be considered where a decision has been made to perform brain death tests; where there is a catastrophic brain injury with GCS 3–4 that cannot be explained by sedation, after a period of observation to allow prognostication; or where there is an intention to discuss withdrawal of life-sustaining treatment expected to result in circulatory death."},{"id":"s3","heading":"Decoupling","body":"The diagnosis of death and the request for donation are separated. The family is informed of the death and must understand and accept it before donation is raised, and the donation conversation is usually led by a transplant coordinator rather than the treating team."},{"id":"s4","heading":"Time is not the enemy","body":"Han et al. (2017) reviewed 107 brain-dead potential donors. The overall consent rate was 58%. Families deciding within 48 hours consented at 55%; those taking longer consented at 73%. Delay did not reduce consent, which supports continuing to counsel and support a family rather than pressing for an immediate answer."}]}'::jsonb
) on conflict (module_slug, slug) do update set
