insert into learn_modules (
  slug, level_slug, position, title, number, core_question, intro_markdown,
  est_minutes, is_mandatory
) values (
  'basics-of-organ-donation', 'beginner', 2, 'The Basics of Organ Donation', 3,
  'What actually happens when someone becomes a donor?', 'You now know who is waiting, and where donations are lost. This module fills in the mechanism in between.

It stays deliberately simple. There are only four routes to donation, and knowing which is which is enough to answer most questions you will be asked in an ordinary conversation.', 10,
  true
) on conflict (slug) do update set
  level_slug = excluded.level_slug, position = excluded.position,
  title = excluded.title, number = excluded.number,
  core_question = excluded.core_question, intro_markdown = excluded.intro_markdown,
  est_minutes = excluded.est_minutes, is_mandatory = excluded.is_mandatory,
  updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'intro', 'basics-of-organ-donation', 0, 'Why this matters', 'INTRO',
  'People do not usually ask advocates technical questions. They ask practical ones: *How does it actually work? Do you have to be dead? Can you donate while you''re alive? What''s the difference between organs and tissue?*

This module gives you clear answers to exactly those questions.

Two facts frame everything that follows. **Organ donation can only take place in a clinical setting** — in practice, an intensive care unit. And **early identification and good management of a potential donor are what make a successful donation possible**; a donation is not a single decision but a process that has to be supported from the beginning.', NULL,
  NULL
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'routes-to-donation', 'basics-of-organ-donation', 1, 'The routes to donation', 'PRIMARY',
  NULL, 'ComparePanel',
  '{"intro":"There are four routes to donation, and the differences matter. Compare them side by side.","columns":[{"id":"dbd","label":"After brain death","caption":"Donation after brain death (DBD)","emphasis":true},{"id":"dcd","label":"After circulatory death","caption":"Donation after circulatory death (DCD)"},{"id":"living","label":"Living donation","caption":"From a living donor"},{"id":"tissue","label":"Tissue donation","caption":"Tissue rather than solid organs"}],"rows":[{"id":"when","label":"When it happens","cells":{"dbd":"A patient on a mechanical ventilator is declared brain dead by two doctors.","dcd":"In palliative care settings, where treatment is withdrawn and death is imminent.","living":"While the donor is alive and well, by their own conscious decision.","tissue":"Irrespective of the manner of death — and even after the body has been moved to a mortuary."}},{"id":"what","label":"What can be donated","cells":{"dbd":"Heart, lungs, liver, kidneys and pancreas, plus tissue.","dcd":"Depends on the circumstances and how quickly recovery can follow death.","living":"A kidney, or a segment of liver.","tissue":"Corneas, bone and ligaments, skin, heart valves."}},{"id":"who-consents","label":"Who gives consent","cells":{"dbd":"Next of kin — spouse, parent, child, brother or sister — or a legal guardian.","dcd":"Next of kin or a legal guardian, as above.","living":"The donor themselves.","tissue":"Next of kin. A tissue donation coordinator is specifically trained to counsel next of kin and obtain consent for tissue-only donations."}},{"id":"setting","label":"Where it happens","cells":{"dbd":"Intensive care, then an operating theatre.","dcd":"Intensive care or a palliative setting, then an operating theatre.","living":"A planned operation, with the donor fully assessed beforehand.","tissue":"Wider range of settings, including after transfer to a mortuary."}}],"bottomLine":"Most deceased organ donation in South Africa follows one of two routes — after brain death, or after circulatory death — and both require consent from next of kin. Tissue donation is possible far more widely than most people assume."}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'takeaways', 'basics-of-organ-donation', 2, 'Key takeaways', 'TAKEAWAYS',
  NULL, 'TakeawayList',
  '{"takeaways":[{"id":"t1","text":"Deceased organ donation follows two routes: donation after brain death (DBD), and donation after circulatory death (DCD)."},{"id":"t2","text":"Living donation is possible for a kidney or a segment of liver, by the donor''s own conscious decision."},{"id":"t3","text":"Tissue donation is much broader: it can occur irrespective of the manner of death, and even after the body has been moved to a mortuary."},{"id":"t4","text":"Organ donation can only take place in a clinical setting. Early identification and good donor management are what make it possible."},{"id":"t5","text":"Every deceased donation route requires consent from next of kin — which is why the family conversation is never optional."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

