insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'study-guide', 'basics-of-organ-donation', 4, 'Study guide', 'STUDY_GUIDE',
  NULL, NULL,
  '{"summary":"The routes to donation, drawn from study guide Objective 5 and the SATCS Red File.","sections":[{"id":"s1","heading":"Donation after brain death (DBD)","body":"Occurs when a patient on a mechanical ventilator is declared brain dead by two doctors. Any patient declared brain dead — irreversible structural brain damage with total loss of brainstem function — is a potential organ donor."},{"id":"s2","heading":"Donation after circulatory death (DCD)","body":"Possible in palliative care settings where treatment is withdrawn and death is imminent."},{"id":"s3","heading":"Living donation","body":"Living organ donors are eligible if they make a conscious decision to donate a kidney or a segment of liver."},{"id":"s4","heading":"Tissue donation","body":"Tissue donation eligibility is broader than organ donation. It can occur irrespective of the manner of death, and even after the body has been moved to a mortuary. A tissue donation coordinator is specifically trained to counsel next of kin and obtain consent for tissue-only donations."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

