insert into learn_modules (
  slug, level_slug, position, title, number, core_question, intro_markdown,
  est_minutes, is_mandatory
) values (
  'having-the-conversation', 'beginner', 3, 'Having the Conversation', 4,
  'How do I actually talk to someone about organ donation?', 'This is where the Beginner level pays off.

Everything you have learned so far exists to support one thing: a conversation with the people you love. Not a debate, not a campaign — a conversation.

Save7''s position is simple. Whether it is a public awareness campaign or a quiet word with your family, the most important part is simply starting the conversation.', 12,
  true
) on conflict (slug) do update set
  level_slug = excluded.level_slug, position = excluded.position,
  title = excluded.title, number = excluded.number,
  core_question = excluded.core_question, intro_markdown = excluded.intro_markdown,
  est_minutes = excluded.est_minutes, is_mandatory = excluded.is_mandatory,
  updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'intro', 'having-the-conversation', 0, 'Why this matters', 'INTRO',
  'The purpose of this module is **not** to teach you to win arguments.

People who feel argued with dig in. People who feel heard reconsider. So the skills that matter here are listening, acknowledging what someone is actually worried about, correcting misinformation gently, and pointing to reliable information rather than to your own authority.

There is good evidence that the conversation itself has value regardless of the outcome: having discussions about donation as part of end-of-life care helps families **independent of what they ultimately decide**. You are not only recruiting donors. You are making sure people are not left guessing.

You are also allowed to say *I don''t know*. It is a far better answer than a confident guess, and it protects the trust that makes the next conversation possible.', NULL,
  NULL
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'practise-responding', 'having-the-conversation', 1, 'Practise responding', 'PRIMARY',
  NULL, 'ScenarioDialogue',
  '{"intro":"Four conversations you are likely to have. Read what the person says, think about what is really behind it, then choose how you would respond. There is often more than one reasonable answer.","scenarios":[{"id":"s1","speaker":"A friend","quote":"If I''m an organ donor, doctors won''t try as hard to save me.","whatsReallyHappening":"This is a fear about being abandoned when you are most vulnerable. It is not really a question about hospital policy.","reflectPrompt":"Before you look at the options — what would you actually say to a friend who said this?","options":[{"id":"o1","text":"That''s a myth. It''s completely untrue and there''s no evidence for it.","quality":"poor","feedback":"Accurate in substance, but it dismisses the fear rather than addressing it. Being told you are wrong rarely changes what you believe — and your friend will simply stop raising it with you."},{"id":"o2","text":"That''s a really common worry, and it makes sense — nobody wants to feel like a number. Can I tell you how the teams are actually kept separate?","quality":"strong","feedback":"This acknowledges the emotion first, normalises the worry so your friend does not feel foolish, and then asks permission before offering information. Permission matters: it turns a correction into a conversation. And the fact you are about to give is a strong one — two independent doctors must certify brain death, and neither may be part of the transplant team."},{"id":"o3","text":"Honestly, I had the same thought. What changed my mind was learning that the law requires two independent doctors to confirm death, and neither of them can be on the transplant team.","quality":"strong","feedback":"Sharing that you had the same doubt removes the hierarchy from the conversation, and you have given the specific safeguard rather than a general reassurance. This is the strongest single fact you have for this objection."},{"id":"o4","text":"Do you really think doctors would do that? They take an oath.","quality":"poor","feedback":"This makes your friend defend themselves, and appeals to professional character rather than explaining what actually prevents the conflict. The conversation is now an argument."}],"debrief":"Notice what the strong responses have in common: they name the emotion, they do not make the person feel stupid, and they offer a concrete safeguard rather than an assurance about good intentions. The separation of the two medical teams is written into the requirements for certifying death — it is not left to trust."},{"id":"s2","speaker":"A family member","quote":"I don''t want doctors cutting me up after I''m dead.","whatsReallyHappening":"Almost never a factual objection. This is about dignity, and about the body of someone loved being treated with respect.","reflectPrompt":"What is this person actually asking you to reassure them about?","options":[{"id":"o1","text":"Recovery is done in an operating theatre with the same care as any other surgery, and the body is restored to its original state afterwards. Would it help to know more about what actually happens?","quality":"strong","feedback":"Answers the real concern — dignity — with a specific fact, and offers detail without forcing it on them. That the body is restored afterwards is exactly the reassurance this objection is asking for."},{"id":"o2","text":"You won''t feel anything, you''ll be dead.","quality":"poor","feedback":"Technically responsive and emotionally tone-deaf. The objection was never about pain."},{"id":"o3","text":"I understand. Can I ask what worries you most about it — is it how you''d look, or something else?","quality":"strong","feedback":"A genuinely good move. You do not yet know whether this is about an open casket, religious washing rites, or something else entirely. Asking beats assuming."},{"id":"o4","text":"Think of it this way — you won''t need your organs any more, but seven other people will.","quality":"workable","feedback":"The reframe is memorable and true, and the number is right. But leading with it before acknowledging the concern can feel like being sold to. Try it after they feel heard, not instead."}],"debrief":"When an objection is about dignity, information alone will not resolve it — but the right information helps. Two specifics are worth knowing: the body is restored to its original state after recovery, and anaesthesia is given to the deceased to reduce the remaining physiologic response to the surgery. Both are the kind of concrete detail that reassures a family far more than a general promise of respect."},{"id":"s3","speaker":"Someone at a community event","quote":"My religion doesn''t allow organ donation.","whatsReallyHappening":"This may be accurate, or it may be an inherited assumption that has never been checked with their own faith leader. Either way, it is not yours to overrule.","reflectPrompt":"What is the line you should not cross here?","options":[{"id":"o1","text":"Actually most major religions do permit organ donation.","quality":"poor","feedback":"Even where broadly true, telling someone what their own faith permits is overstepping. You have made yourself an authority on their beliefs, and lost their trust."},{"id":"o2","text":"Thank you for telling me — that''s important, and I''d never want to push against it. Some people find it useful to ask their own faith leader directly, because positions vary. Would that be worth doing?","quality":"strong","feedback":"Respects their belief, stays inside your competence, and points them to the right authority — their faith leader, not you. In hospital, a faith representative or chaplain can be included to support a family for exactly this reason."},{"id":"o3","text":"That''s fine. Would you still be willing to talk to your family about what you''d want, so they aren''t left guessing?","quality":"strong","feedback":"Excellent. It accepts their position completely and still advances Save7''s actual goal: that families know each other''s wishes. Since consent from next of kin is always required, a clearly communicated ''no'' is genuinely useful — it spares a family an impossible guess."},{"id":"o4","text":"Which religion? I can look up what they say about it.","quality":"workable","feedback":"Well-intentioned, but it puts you in the position of interpreting their faith to them. Better to point them to someone inside their own tradition."}],"debrief":"Save7''s goal is not to convert anyone. Donation is possible from all communities and cultures in South Africa, and it should never be assumed that someone''s background means the subject shouldn''t be raised — but nor is it yours to settle. Someone who declines donation and has told their family is a success, not a failure."},{"id":"s4","speaker":"A colleague","quote":"I''d probably be turned down anyway — I''m in my sixties and I''m on medication for blood pressure.","whatsReallyHappening":"Self-exclusion. This person has quietly ruled themselves out and would never have raised it if you had not been talking about donation.","reflectPrompt":"Why is this one of the most valuable conversations you can have?","options":[{"id":"o1","text":"Please don''t rule yourself out — there''s actually no age restriction for solid organ donation, and conditions like high blood pressure don''t automatically exclude someone. It''s assessed organ by organ at the time.","quality":"strong","feedback":"Exactly right, and specific. There is no age limit for solid organ donation, and extended criteria donors with conditions such as hypertension, diabetes or HIV may still be eligible if individual organs are assessed as transplantable."},{"id":"o2","text":"Age and blood pressure don''t matter at all for donation.","quality":"poor","feedback":"Overcorrection. These factors are assessed rather than ignored, and claiming they are irrelevant damages your credibility when someone checks."},{"id":"o3","text":"That''s really common to assume. The decision isn''t yours or mine to make — it''s a medical assessment at the time, so the best thing is to register your wishes, tell your family, and let the doctors decide.","quality":"strong","feedback":"Puts the decision where it belongs and gives your colleague two concrete things to do."},{"id":"o4","text":"You could still donate your corneas, probably.","quality":"workable","feedback":"Tissue donation is a genuinely useful point, and cornea donors are generally accepted between 6 and 65 — so at 60-something this may well be accurate. But ''probably'' is speculation about a specific outcome; keep the framing general and let the assessment decide."}],"debrief":"Self-exclusion is invisible unless you start the conversation. The single most useful sentence here is that there is no age restriction for solid organ donation. Module 8 covers eligibility properly."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'takeaways', 'having-the-conversation', 2, 'Key takeaways', 'TAKEAWAYS',
  NULL, 'TakeawayList',
  '{"takeaways":[{"id":"t1","text":"The goal is a conversation, not a conversion. Because consent from next of kin is always required, someone who decides against donation but tells their family has still done something valuable."},{"id":"t2","text":"Acknowledge the emotion before you correct the facts. People who feel dismissed stop listening."},{"id":"t3","text":"Ask permission before informing. It turns a correction into a conversation."},{"id":"t4","text":"Your strongest single fact: two independent doctors must certify brain death, and neither may be part of the transplant team."},{"id":"t5","text":"For dignity concerns: the body is restored to its original state after recovery, and anaesthesia is given to the deceased during it."},{"id":"t6","text":"Stay inside your competence. Never tell someone what their own religion permits — point them to their faith leader."},{"id":"t7","text":"\"I don''t know, let me find out\" protects your credibility and the next conversation."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

