insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'study-guide', 'having-the-conversation', 4, 'Study guide', 'STUDY_GUIDE',
  NULL, NULL,
  '{"summary":"Respectful conversation practice, and the facts that support it.","sections":[{"id":"s1","heading":"Why talking to your family matters","body":"Consent from next of kin is always required for donation to proceed. A registration your family has never heard about leaves them guessing at the worst possible moment. Evidence also suggests that discussing donation as part of end-of-life care helps families regardless of what they decide."},{"id":"s2","heading":"The four facts worth memorising","bullets":["Two independent doctors must certify brain death, and neither may be part of the transplant team","The body is restored to its original state after recovery surgery, and anaesthesia is given to the deceased during it","There is no age restriction for solid organ donation","The donor''s medical aid, estate and next of kin bear no costs for the donation once death is declared and consent obtained"]},{"id":"s3","heading":"How to approach the subject","body":"Acknowledge the emotion first. Ask permission before offering information. Do not overcorrect — claiming a factor is irrelevant is as inaccurate as claiming it disqualifies. Stay inside your competence, particularly on matters of faith. And say when you do not know."},{"id":"s4","heading":"What counts as success","body":"A family that has talked. Not a signature."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

