insert into learn_modules (
  slug, level_slug, position, title, number, core_question, intro_markdown,
  est_minutes, is_mandatory
) values (
  'journey-of-a-gift', 'intermediate', 0, 'The Journey of a Gift', 5,
  'What is the full journey from a potential donor to a recipient''s new life?', 'In Module 2 you walked this pathway looking for the places it breaks. Now you walk it properly, end to end, as the people living through it experience it.

Save7''s film *The Journey of a Gift* follows that journey. This module is built around it — not as a video to watch and move past, but as the thread you follow through each stage.', 16,
  true
) on conflict (slug) do update set
  level_slug = excluded.level_slug, position = excluded.position,
  title = excluded.title, number = excluded.number,
  core_question = excluded.core_question, intro_markdown = excluded.intro_markdown,
  est_minutes = excluded.est_minutes, is_mandatory = excluded.is_mandatory,
  updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'intro', 'journey-of-a-gift', 0, 'Why this matters', 'INTRO',
  'A donation is not an event. It is a chain of decisions and actions, running over hours, involving dozens of people, most of whom never meet each other and none of whom meet the recipient.

Understanding the whole arc is what lets you answer the question people most often ask an advocate: *so what actually happens?*

Two stages in particular are almost never mentioned in public conversation, and both change how the process is understood. **Donor management** is skilled, active care given after death has been determined — it is the reason a donation succeeds or fails. And **allocation** is a matching process, not a queue.', NULL,
  NULL
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'watch-the-journey', 'journey-of-a-gift', 1, 'The Journey of a Gift', 'PRIMARY',
  NULL, 'ChapterVideo',
  '{"title":"The Journey of a Gift","src":"/media/journey-of-a-gift.mp4","durationSeconds":419,"awaitingAsset":false,"chapters":[{"id":"c1","label":"Why transplantation is needed","startSeconds":0,"summary":"One donor can save seven or more lives."},{"id":"c2","label":"Who is waiting for a transplant","startSeconds":0},{"id":"c3","label":"Identification and referral","startSeconds":0},{"id":"c4","label":"Determination of death","startSeconds":0},{"id":"c5","label":"The family approach and consent","startSeconds":0},{"id":"c6","label":"Donor management","startSeconds":0},{"id":"c7","label":"Recovery and allocation","startSeconds":0},{"id":"c8","label":"Transplantation","startSeconds":0},{"id":"c9","label":"A life after transplant","startSeconds":0}]}'::jsonb
) on conflict (module_slug, slug) do update set
