insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'the-full-journey', 'journey-of-a-gift', 2, 'The full journey, step by step', 'PRIMARY',
  NULL, 'PathwayJourney',
  '{"intro":"The complete pathway, including the stages Module 2 did not cover: donor management, allocation, and what happens to the recipient afterwards.","showLossPoints":false,"steps":[{"id":"potential-donor","label":"Potential donor","summary":"Where the journey begins.","detail":"Organ donation can only happen in a clinical setting, almost always an intensive care unit with the patient on a mechanical ventilator. The most common routes to becoming a potential donor are traumatic head injury, stroke, or cerebral hypoxia following drowning or drug overdose."},{"id":"identification","label":"Identification","summary":"A clinical team recognises that donation may be possible.","detail":"Three triggers should prompt consideration in any mechanically ventilated patient: a decision has been made to perform brain death tests; there is a catastrophic brain injury with GCS 3–4 that cannot be explained by sedation, after a period of observation to allow prognostication; or there is an intention to discuss withdrawal of life-sustaining treatment expected to result in circulatory death.\n\nIdentification is the responsibility of the primary treatment team — the doctors and nurses already caring for the patient — as part of end-of-life care."},{"id":"referral","label":"Referral","summary":"A transplant or tissue donation coordinator is contacted.","detail":"The earliest possible discussion with a transplant coordinator is recommended. It lets the coordinator screen the patient, identify when donation is not feasible, and mobilise support — which minimises delay for the family. Importantly, this first discussion with the coordinator happens *before* end-of-life matters are raised with the family.\n\nThere is no legal requirement to refer. Referral happens because a clinician chooses to make it happen."},{"id":"determination-of-death","label":"Determination of death","summary":"Death is formally determined by two independent clinicians.","detail":"Two registered medical doctors must certify brain death. Neither may be involved with a transplantation team, and one must have been registered with the HPCSA for at least five years. Legal death is the time at which both doctors have confirmed brain death after completing all required clinical tests.\n\nModule 6 covers this in full."},{"id":"family-approach","label":"Family approach","summary":"The family is told about the death — and donation is not yet mentioned.","detail":"This is the step people find most surprising. The family is informed of the diagnosis and must fully understand and accept that their relative has died, **before organ donation is raised at all**. The treating team does not raise it; a transplant coordinator does, afterwards.\n\nThis deliberate separation is called **decoupling**. It exists so that a family is never asked to absorb a death and make a donation decision in the same breath — and so that the diagnosis is never heard as a request.\n\nAccepting the diagnosis takes patience and empathy from everyone involved. Families are given a specific period to process it, and support is not withdrawn immediately."},{"id":"consent","label":"Consent","summary":"Consent is sought from the person’s own decision first, then relatives in statutory order.","detail":"Where the person made no donation while alive, consent comes from relatives in the order section 62(2) sets out: spouse, partner, major child, parent, guardian, major brother, major sister. “Major” means adult, and a partner ranks above every relative but a spouse. There is an ethical obligation to give every family the chance to make a fully informed decision, and nobody should be excluded from being offered the option.\n\nIf the death was unnatural, it must also go for a medico-legal post-mortem, and recovery needs the forensic pathologist’s authorisation. Institutional authorisation comes in writing from the medical practitioner in charge of clinical services at the hospital. Module 9 covers the legal detail."},{"id":"donor-management","label":"Donor management","summary":"Active, skilled care that keeps the gift viable.","detail":"Care of the potential donor continues the support that began before death was declared, and actively manages the physiological deterioration that follows brain death. **Active management improves both the number of organs recovered and the outcomes for recipients** — this is not holding care, it is treatment with a purpose.\n\nIt includes gentle but effective ventilation and good pulmonary care, positioning the patient head-up at 30 to 45 degrees, and active temperature control, since the loss of hypothalamic function means the body can no longer regulate its own temperature. Fluid balance is kept deliberately restrictive, which improves lung viability without measurably harming kidney outcomes.\n\nFamilies may stay with their relative during this period, including up to the point of transfer to theatre."},{"id":"recovery","label":"Organ and tissue recovery","summary":"Surgery, performed with the same care and respect as any operation.","detail":"Recovery takes place in an operating theatre. Anaesthesia is given to the deceased in order to reduce the remaining physiological response to the surgery. Tissue is recovered by trained tissue recovery technicians, ethically and respectfully. The body is restored to its original state afterwards.\n\nFamilies commonly ask about the procedure itself, about anaesthesia, and about how their relative will be transferred to a funeral home. All three are reasonable questions with straightforward answers."},{"id":"allocation","label":"Allocation","summary":"Organs are matched to recipients — not handed out in order.","detail":"Allocation is a matching process. One concrete rule worth knowing: paediatric donors under 18 are preferentially allocated to paediatric recipients under 18.\n\nThere is also a system-level effect that is easy to miss. Long-term outcomes improve when there is a larger pool of donors to allocate from — so a donation that is lost does not only cost one recipient, it makes matching worse for everyone waiting."},{"id":"transplantation","label":"Transplantation","summary":"The transplant operation itself.","detail":"For the recipient this is the beginning rather than the end. Module 11 follows what happens next."},{"id":"life-after","label":"Life after transplant","summary":"A lifelong medical journey, not a completed repair.","detail":"A transplant restores something specific — sight, breathing, freedom from dialysis, years of active living — and it brings ongoing medication and monitoring with it. Describing both honestly is what makes an advocate credible."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'takeaways', 'journey-of-a-gift', 3, 'Key takeaways', 'TAKEAWAYS',
  NULL, 'TakeawayList',
  '{"takeaways":[{"id":"t1","text":"Donation is a coordinated chain of events over hours, not a single moment."},{"id":"t2","text":"The diagnosis conversation and the donation conversation are deliberately separated. This is called decoupling.","detail":"The family must understand and accept the death before donation is raised — and it is raised by a coordinator, not by the treating team."},{"id":"t3","text":"Donor management is active, skilled care after death has been determined. It measurably improves how many organs are recovered and how well recipients do."},{"id":"t4","text":"Recovery is surgery in an operating theatre. Anaesthesia is given to the deceased, and the body is restored to its original state afterwards."},{"id":"t5","text":"Allocation is matching, not queueing. Paediatric donors are preferentially allocated to paediatric recipients."},{"id":"t6","text":"A larger donor pool improves outcomes for everyone waiting — so a lost donation costs more than one transplant."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

