insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'study-guide', 'journey-of-a-gift', 5, 'Study guide', 'STUDY_GUIDE',
  NULL, NULL,
  '{"summary":"The donation pathway, end to end.","sections":[{"id":"s1","heading":"Identification and referral","body":"Three triggers should prompt consideration of donation in a mechanically ventilated patient: a decision to perform brain death tests; catastrophic brain injury with GCS 3–4 not explained by sedation, after observation for prognostication; or intended discussion of withdrawal of life-sustaining treatment expected to result in circulatory death. The earliest possible discussion with a transplant coordinator is recommended, and occurs before end-of-life matters are raised with the family."},{"id":"s2","heading":"Decoupling","body":"The family is informed of the death and must fully understand and accept it before donation is mentioned. The donation conversation is then initiated by a transplant coordinator. Families are given a defined period to process the diagnosis, and support is not withdrawn immediately."},{"id":"s3","heading":"Donor management","body":"Care continues the support begun before death was declared and actively manages the physiological deterioration that follows. Active management improves organ retrieval rates and transplant outcomes. Components include gentle effective ventilation with good pulmonary care, head-up positioning at 30–45 degrees, active temperature control following loss of hypothalamic function, and a restrictive fluid balance that improves lung viability without substantially affecting kidney outcomes."},{"id":"s4","heading":"Recovery","body":"Performed in an operating theatre. Anaesthesia is given to the deceased to decrease the remaining physiologic response to the procedures involved. Tissue is recovered by trained technicians. The body is restored to its original state."},{"id":"s5","heading":"Allocation","body":"A matching process. Paediatric donors under 18 are preferentially allocated to paediatric recipients under 18. Long-term outcomes are improved by having a large pool from which to allocate organs."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
