insert into learn_modules (
  slug, level_slug, position, title, number, core_question, intro_markdown,
  est_minutes, is_mandatory
) values (
  'what-does-death-mean', 'intermediate', 1, 'What Does Death Mean?', 6,
  'How can someone be declared dead while their heart is still beating?', 'This is the question that stops donation conversations dead, and the one most advocates feel least equipped to answer.

It deserves a careful answer, so this module follows the South African Guidelines on the Determination of Death closely rather than paraphrasing loosely. Getting this wrong — in either direction — damages trust in the whole system.

**One distinction matters more than anything else in this course: brain death is not a coma, and it is not simply being unconscious.**', 16,
  true
) on conflict (slug) do update set
  level_slug = excluded.level_slug, position = excluded.position,
  title = excluded.title, number = excluded.number,
  core_question = excluded.core_question, intro_markdown = excluded.intro_markdown,
  est_minutes = excluded.est_minutes, is_mandatory = excluded.is_mandatory,
  updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'intro', 'what-does-death-mean', 0, 'Why this matters', 'INTRO',
  'A family sitting beside a ventilated patient sees a warm body and a beating heart. Being told that person has died contradicts what their eyes are telling them.

That contradiction is not stupidity. It is a completely reasonable response to an unusual situation, and it is the single biggest obstacle in the consent conversation.

Start from the definition itself, which is more precise and more useful than most people expect:

> Death is the clinical point of irreversible loss of the capacity for consciousness and the irreversible loss of the capacity to breathe.

Read it twice. It does not mention the heart. Death is determined either by **neurological criteria** or by **circulatory criteria**, and a correctly performed clinical examination can establish it with complete certainty — it is not necessary to wait for signs like rigor mortis before death can be determined in a hospital.

And the fact that answers the objection you will hear most often:

> There is no documented case of a person who fulfils the preconditions and criteria for brain death ever subsequently developing any return of brain function.', NULL,
  NULL
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'brain-death-vs-coma', 'what-does-death-mean', 1, 'Brain death is not a coma', 'PRIMARY',
  NULL, 'ComparePanel',
  '{"intro":"These three states are constantly confused, including in news reporting and film. Compare them carefully — this is the distinction you will be asked to explain most often.","columns":[{"id":"brain-death","label":"Brain death","caption":"Death by neurological criteria","emphasis":true},{"id":"coma","label":"Coma","caption":"Profound unconsciousness"},{"id":"vegetative","label":"Vegetative state","caption":"Wakefulness without awareness"}],"rows":[{"id":"what","label":"What it is","cells":{"brain-death":"Irreversible structural brain damage with total loss of brainstem function. The capacity for consciousness and the capacity to breathe are both irreversibly gone.","coma":"A state of profound unconsciousness. Brain function is impaired but not irreversibly and totally lost.","vegetative":"Cycles of wakefulness without awareness. Brainstem function is present."}},{"id":"brainstem","label":"Brainstem function","cells":{"brain-death":"Absent — this is what is tested for, and its total loss is the diagnosis.","coma":"Present.","vegetative":"Present."}},{"id":"breathing","label":"Capacity to breathe","cells":{"brain-death":"Irreversibly absent. This is directly tested by an apnoea test, and it is part of the definition of death.","coma":"Usually present, though breathing may need support.","vegetative":"Present."}},{"id":"recovery","label":"Possibility of recovery","cells":{"brain-death":"None. There is no documented case of anyone meeting the preconditions and criteria for brain death subsequently regaining any brain function.","coma":"Possible. People do recover from comas — which is exactly why the two must not be confused.","vegetative":"Limited and variable."}},{"id":"legal","label":"Legal status","cells":{"brain-death":"Dead. Legal death is the time at which two doctors have confirmed brain death after completing all required clinical tests.","coma":"Alive.","vegetative":"Alive."}},{"id":"heart","label":"Why the heart may still be beating","cells":{"brain-death":"A mechanical ventilator is supplying the oxygen the person can no longer obtain for themselves, so the heart continues to beat for a period after death.","coma":"The person is alive; the heart is beating for the ordinary reason.","vegetative":"The person is alive."}}],"bottomLine":"Brain death is death. A coma is not. Conflating them is the most common and most damaging misunderstanding in organ donation."}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'how-death-is-determined', 'what-does-death-mean', 2, 'How death is determined', 'PRIMARY',
  NULL, 'PathwayJourney',
  '{"intro":"Determination of death follows a defined process with deliberate safeguards. Open each step to see what it involves and why it exists.","showLossPoints":false,"steps":[{"id":"preconditions","label":"Preconditions","summary":"Establishing that the criteria can be applied at all.","detail":"There must be an established cause compatible with complete and irreversible loss of all brain function before testing begins. The patient must also be physiologically stable enough for the tests to mean anything: a temperature of at least 36°C, and a systolic blood pressure above 100 mmHg or a mean arterial pressure above 60 mmHg (with age-appropriate targets in children)."},{"id":"exclusions","label":"Excluding what could mimic it","summary":"Ruling out reversible causes before concluding anything.","detail":"The influence of drugs that depress the central nervous system must be excluded — for example by allowing five elimination half-lives to pass. Where severe alcohol intoxication may be the cause of the coma, the blood level should be shown to be below 80 mg/dL. Metabolic and endocrine disturbances are considered, though the guidelines stress that the most important factor is an unequivocal cause for the coma."},{"id":"observation","label":"Observation period","summary":"Time to be certain the injury is what it appears to be.","detail":"No single standard observation period is set — it is judged case by case. Two situations are specified: in anoxic brain injury the observation period should be 24 hours, and where therapeutic hypothermia has been used there should be 24 hours of normal temperature before examination. A cautious approach is advised in children, where confounders are common."},{"id":"clinical-assessment","label":"Clinical assessment","summary":"Structured examination of brainstem function.","detail":"It must be possible to examine the brainstem reflexes properly — at least one eye and one ear — and to perform an apnoea test safely.\n\nThe assessment of coma gives a sense of the rigour involved: deep pressure is applied to a nail bed on each limb and to the sternum. Noxious stimuli must produce no grimacing, no facial movement and no limb response other than reflexes mediated by the spinal cord. Any response that is not spinal in origin is incompatible with a diagnosis of brain death. Distinguishing the two requires expertise, and consultation is recommended where a response is unclear."},{"id":"apnoea-testing","label":"Apnoea testing","summary":"Testing directly for any capacity to breathe.","detail":"Because the irreversible loss of the capacity to breathe is part of the definition of death, it is tested directly rather than inferred. Where two doctors test separately there is no required delay between their examinations, but the guidelines strongly advocate that a single apnoea test be performed by both doctors together."},{"id":"ancillary","label":"Ancillary testing","summary":"For the situations where clinical testing is not possible.","detail":"An ancillary test is an additional investigation that assists the clinical diagnosis. It is used where clinical testing cannot be completed — for instance where apnoea testing is precluded by severe hypoxic respiratory failure or a high cervical cord injury — after confirming that brainstem reflexes are absent. It supplements the clinical diagnosis rather than replacing it."},{"id":"independent-assessment","label":"Two independent doctors","summary":"The safeguard that answers the most common public fear.","detail":"Two registered medical doctors must certify brain death. **Neither may be involved with a transplantation team.** One must have been registered with the HPCSA for at least five years, and may not be an intern. The two should ideally perform the testing together.\n\nLegal death is the time at which both doctors have confirmed brain death after completing all required clinical tests."},{"id":"children","label":"Children","summary":"The same standard, with one hard limit.","detail":"Determination of death in children is held to the same standard as in adults. It cannot be diagnosed in children below 36 weeks corrected gestation."},{"id":"accommodation","label":"Accommodation and somatic support","summary":"Two terms worth knowing, because they are humane ones.","detail":"**Somatic support** is the management of the body and organs, excluding the brain, after brain death has been confirmed.\n\n**Accommodation** is a period of somatic support provided specifically to allow a family time to process the diagnosis of death. The guidelines make recommendations on handling family requests for it — which tells you something about the spirit in which they were written."},{"id":"circulatory","label":"Circulatory determination of death","summary":"The other route by which death is determined.","detail":"Death may also be determined by circulatory criteria — the preferred term over older phrases like cardiac or cardiorespiratory death. This is the route relevant to donation after circulatory death, where treatment is withdrawn in a palliative setting and death is expected."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'takeaways', 'what-does-death-mean', 3, 'Key takeaways', 'TAKEAWAYS',
  NULL, 'TakeawayList',
  '{"takeaways":[{"id":"t1","text":"Death is the irreversible loss of the capacity for consciousness together with the irreversible loss of the capacity to breathe. The definition does not mention the heart."},{"id":"t2","text":"Brain death is not a coma and not simply unconsciousness. Recovery from a coma is possible; there is no documented case of recovery of brain function after brain death was properly determined."},{"id":"t3","text":"The heart can keep beating because a ventilator is supplying oxygen the person can no longer obtain for themselves."},{"id":"t4","text":"Two registered doctors must certify brain death, neither of them involved with a transplant team, and one registered with the HPCSA for at least five years."},{"id":"t5","text":"The capacity to breathe is tested directly, by an apnoea test — it is not assumed."},{"id":"t6","text":"Legal death is the moment both doctors have confirmed brain death after completing all required tests."},{"id":"t7","text":"A family''s disbelief at the bedside is a reasonable human response, not ignorance. Accepting the diagnosis takes patience and empathy, and “accommodation” exists to give them time."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

