insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'study-guide', 'what-does-death-mean', 5, 'Study guide', 'STUDY_GUIDE',
  NULL, NULL,
  '{"summary":"Based on the South African Guidelines on the Determination of Death (Critical Care Society of Southern Africa, 2021).","sections":[{"id":"s1","heading":"The definition","body":"Death is the clinical point of irreversible loss of the capacity for consciousness and the irreversible loss of the capacity to breathe. Death is determined by either neurological or circulatory criteria, in accordance with accepted medical standards. A correctly performed clinical examination can determine the point of death with complete certainty; it is not necessary to wait for signs such as hypostasis, rigor mortis or decay in the healthcare setting."},{"id":"s2","heading":"Terminology","bullets":["Brain death, or death by neurological criteria — the preferred term, in place of brain-stem death","Circulatory death, or death by circulatory criteria — preferred over cardiac or cardiorespiratory death","Somatic support — management of the body and organs, excluding the brain, after brain death is confirmed","Accommodation — a period of somatic support to allow a family to process the diagnosis","Ancillary test — an additional test that assists the clinical diagnosis of brain death"]},{"id":"s3","heading":"Preconditions for brain death testing","bullets":["An established cause compatible with complete and irreversible loss of all brain function","Temperature of at least 36°C","Systolic blood pressure above 100 mmHg, or mean arterial pressure above 60 mmHg","Exclusion of CNS-depressing drugs, for example by allowing five elimination half-lives","Where severe alcohol intoxication is a concern, a blood level below 80 mg/dL","Ability to examine brainstem reflexes — at least one eye and one ear — and to perform apnoea testing safely"]},{"id":"s4","heading":"Observation periods","body":"No single standard period is set; it is judged case by case. In anoxic brain injury the observation period should be 24 hours. Where therapeutic hypothermia has been used, 24 hours of normothermia should pass before examination. A cautious approach is advised in paediatrics."},{"id":"s5","heading":"Who determines death","body":"Two registered medical doctors, neither involved with a transplantation team, one of whom must have been registered with the HPCSA for at least five years and may not be an intern. They should ideally test together, and a single apnoea test performed by both together is strongly advocated. Legal death is the time both have confirmed brain death after completing all required clinical tests."},{"id":"s6","heading":"Children","body":"Held to the same standard as adults, but brain death cannot be diagnosed in children below 36 weeks corrected gestation."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

