insert into learn_modules (
  slug, level_slug, position, title, number, core_question, intro_markdown,
  est_minutes, is_mandatory
) values (
  'who-makes-it-happen', 'intermediate', 2, 'Who Makes It Happen?', 7,
  'Who are all the people involved in a single donation?', 'Donation is often imagined as something two surgeons do. It is closer to a relay involving a dozen roles, several of which most people have never heard of.

Meet the team. Knowing who does what is genuinely useful in conversation — it makes the process concrete, and it answers questions about safeguards without you having to make claims about them.', 12,
  true
) on conflict (slug) do update set
  level_slug = excluded.level_slug, position = excluded.position,
  title = excluded.title, number = excluded.number,
  core_question = excluded.core_question, intro_markdown = excluded.intro_markdown,
  est_minutes = excluded.est_minutes, is_mandatory = excluded.is_mandatory,
  updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'intro', 'who-makes-it-happen', 0, 'Why this matters', 'INTRO',
  'Two things become obvious once you see the full team.

The first is how much care surrounds a donation. The second is how many of these roles exist specifically as safeguards — people whose job is to make sure the process is done properly and that a family is supported through it.

That is a far more reassuring answer to a sceptical question than any assertion you could make yourself. As the SATCS Red File puts it: organ and tissue donation is a team effort, and you are a crucial part of the team.', NULL,
  NULL
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'meet-the-team', 'who-makes-it-happen', 1, 'Meet the transplant team', 'PRIMARY',
  NULL, 'TeamRoster',
  '{"intro":"Select any role to see what that person or organisation actually does.","members":[{"id":"treating-team","role":"Primary treatment team","oneLiner":"Cares for the patient long before donation is considered — and identifies the possibility.","appearsAt":"Before and during identification","responsibilities":["Provides the critical care the patient is already receiving","Responsible for the initial identification of a potential donor, as part of end-of-life care","Makes the referral to a transplant coordinator","Counsels the family on prognosis, and later delivers the diagnosis of death — without raising donation at that point"]},{"id":"transplant-coordinator","role":"Transplant coordinator","oneLiner":"The central figure who coordinates the entire process.","appearsAt":"From referral through to recovery","responsibilities":["Performs donor assessments and screens for suitability","Oversees donor management","Coordinates the entire donation process","Leads the donation conversation with the family, after the death has been accepted"]},{"id":"tissue-coordinator","role":"Tissue donation coordinator","oneLiner":"Specifically trained to counsel families and obtain consent for tissue-only donation.","appearsAt":"Referral onwards","responsibilities":["Counsels next of kin about tissue donation","Obtains consent for tissue-only donations"]},{"id":"death-determining-doctors","role":"The two doctors who certify death","oneLiner":"Independent of the transplant team — a legal safeguard, not a courtesy.","appearsAt":"Determination of death","responsibilities":["Two registered medical doctors are legally required to certify brain death","Neither may be part of the transplant team","One must have been registered with the HPCSA for at least five years, and may not be an intern","Ideally perform the testing together, including a single shared apnoea test"]},{"id":"nurses","role":"Nurses","oneLiner":"Continuous care for the patient, and continuous presence for the family.","appearsAt":"Throughout","responsibilities":["Deliver the ongoing critical care the patient and then the donor requires","Part of the identification and referral responsibility of the treatment team","Often the team member a family speaks to most","A nursing sister is typically part of the team that meets with the family"]},{"id":"counsellors","role":"Trauma counsellor","oneLiner":"Supports the family through grief and decision-making.","appearsAt":"Family approach and after","responsibilities":["May form part of the team that approaches the family","Supports families through an acute bereavement","Note that routine grief counselling is generally not indicated — most bereaved people are resilient and grief is integrated with the support of family, friends and spiritual care. Counselling is valuable for complicated grief."]},{"id":"translators","role":"Translator","oneLiner":"Makes consent genuinely informed across a language barrier.","appearsAt":"Family approach and consent","responsibilities":["May form part of the team that approaches the family","Ensures the family understands the diagnosis and the decision they are being asked to make","Consent that is not understood is not informed consent — which makes this a safeguard, not a convenience"]},{"id":"faith-representatives","role":"Faith representative or hospital chaplain","oneLiner":"Supports families within their own religious tradition.","appearsAt":"Family approach and after","responsibilities":["May form part of the team that approaches the family","The responsible consultant and transplant coordinator may explore including a faith representative or hospital chaplain to support families during these discussions","Provides spiritual support, which is part of how most people actually integrate grief"]},{"id":"recovery-technicians","role":"Tissue recovery technicians","oneLiner":"Trained to recover tissue ethically and respectfully.","appearsAt":"Recovery","responsibilities":["Surgically recover tissues","Trained specifically to do so in an ethical and respectful manner"]},{"id":"odf","role":"Organ Donor Foundation (ODF)","oneLiner":"The national umbrella body for awareness and the donor database.","appearsAt":"Before the pathway begins","isOrganisation":true,"externalUrl":"https://odf.org.za","responsibilities":["Serves as the national umbrella body for promoting awareness of organ donation","Manages the national donor database","The right place to send anyone who wants to register, or who asks for current national figures"]},{"id":"satcs","role":"South African Transplant Coordinators Society (SATCS)","oneLiner":"Represents, unites and supports transplant coordinators nationally.","isOrganisation":true,"responsibilities":["Exists to represent, unite and support all transplant coordinators in the country","Publishes the Organ and Tissue Donation Reference File — the Red File — used throughout this course"]},{"id":"save7","role":"Save7","oneLiner":"Awareness, education and donor support — including the LifePod.","isOrganisation":true,"externalUrl":"https://save7.org","responsibilities":["Raises public awareness and enables donor registration","Runs the LifePod, a dedicated support unit for consented organ donors","Produced this course, the Journey of a Gift film, and the 7 Lives in 7 Steps referral pathway"]}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'takeaways', 'who-makes-it-happen', 2, 'Key takeaways', 'TAKEAWAYS',
  NULL, 'TakeawayList',
  '{"takeaways":[{"id":"t1","text":"The transplant coordinator is the central figure: donor assessment, donor management, and coordination of the whole process."},{"id":"t2","text":"The two doctors who certify brain death are independent of the transplant team by law. This is the structural answer to the most common public fear."},{"id":"t3","text":"The team that meets a family typically includes a doctor, a nursing sister and a transplant coordinator, and may include a trauma counsellor, a translator or a faith representative."},{"id":"t4","text":"Translators protect the validity of consent, not just the family''s comfort — consent that is not understood is not informed consent."},{"id":"t5","text":"Identification and referral belong to the primary treatment team, as part of ordinary end-of-life care."},{"id":"t6","text":"Two organisations hold the national picture together: the ODF for awareness and the donor database, and SATCS for the coordinators themselves."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

