insert into learn_modules (
  slug, level_slug, position, title, number, core_question, intro_markdown,
  est_minutes, is_mandatory
) values (
  'who-can-donate', 'intermediate', 3, 'Who Can Donate?', 8,
  'Can I donate if I''m old, sick, or have another medical condition?', 'More potential donors are lost to self-exclusion than most people realise. Someone decides privately that they would not be eligible, and never mentions it again.

This module exists to interrupt that. The headline is simple and, unusually, quite definite:

**There is no age restriction for solid organ donation.**

Beyond that, suitability is assessed organ by organ, at the time, by people qualified to do it — and nobody should be excluded from being offered the option to donate.', 14,
  true
) on conflict (slug) do update set
  level_slug = excluded.level_slug, position = excluded.position,
  title = excluded.title, number = excluded.number,
  core_question = excluded.core_question, intro_markdown = excluded.intro_markdown,
  est_minutes = excluded.est_minutes, is_mandatory = excluded.is_mandatory,
  updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'intro', 'who-can-donate', 0, 'Why this matters', 'INTRO',
  'There is a strong temptation to hand advocates a simple checklist of who can and cannot donate. Mostly that is a bad idea: confident exclusion rules are frequently wrong, and a confident wrong answer from an advocate can permanently remove a potential donor.

But *mostly* is not *always*, and this module is careful about the difference. Two kinds of statement appear here:

- **Where the guidance states a criterion, this course states it too.** Tissue donation has real age ranges, and pretending otherwise would misreport Save7''s own study guide.
- **Where suitability is a clinical judgement, the honest answer is that it is assessed individually** — which covers age for solid organs, and every comorbidity.

The framing that survives both: *don''t rule anyone out on their behalf.*', NULL,
  NULL
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'does-this-rule-me-out', 'who-can-donate', 1, '"Does this rule me out?"', 'PRIMARY',
  NULL, 'EligibilityMatrix',
  '{"intro":"The factors people most often rule themselves out for. Open each one to see the assumption people arrive with, and how the question is actually answered.","bottomLine":"There is no upper age limit for solid organ donation, and hypertension, diabetes and obesity do not disqualify anyone. HIV does not exclude organ donation in South Africa — it has its own established programme — though tissue banks currently do exclude it, which is why the answer depends on what is being donated. Suitability is assessed organ by organ, at the time. Nobody should be excluded from being offered the option to donate.","factors":[{"id":"age-solid-organ","factor":"Age — solid organs","commonAssumption":"\"I''m too old to be a donor.\"","reality":"There is no upper age limit for solid organ donation. Nobody is disqualified by age alone: the organs are assessed at the time of death, and that assessment is what decides. Registering has an age floor rather than a ceiling — 16 to register independently, younger with parental consent.","verdict":"rarely-absolute"},{"id":"hypertension","factor":"High blood pressure","commonAssumption":"\"I''m on medication for hypertension, so I''d be turned down.\"","reality":"Donors with comorbidities such as hypertension are described as extended criteria donors, and may still be eligible if individual organs are assessed as transplantable. It is an assessment, not an exclusion.","verdict":"assessed-individually"},{"id":"diabetes","factor":"Diabetes","commonAssumption":"\"Diabetics can''t donate.\"","reality":"Diabetes is one of the comorbidities explicitly named in the extended criteria donor category. Individual organs are assessed for transplantability.","verdict":"assessed-individually"},{"id":"hiv","factor":"HIV","commonAssumption":"\"Being HIV positive automatically excludes donation.\"","reality":"For **organs**, no — and South Africa led the world here. Groote Schuur Hospital in Cape Town has transplanted kidneys from HIV-positive deceased donors since 2008, into recipients who are themselves HIV positive and on stable treatment with an undetectable viral load. Being HIV positive does not put someone outside donation.\n\nFor **tissue**, the answer is currently different: South African tissue banks list HIV as an exclusion, along with cancer, septicaemia and hepatitis. So the honest answer is *it depends what is being donated* — which is the module’s whole point, and is why an advocate should never answer this from memory.","verdict":"assessed-individually"},{"id":"cause-of-death","factor":"How the person died","commonAssumption":"\"You can only donate after a car accident.\"","reality":"Common routes to brain death include traumatic head injury, stroke, and cerebral hypoxia following drowning or drug overdose. For tissue donation, eligibility does not depend on the manner of death at all.","verdict":"depends"},{"id":"tissue-broadly","factor":"Tissue donation generally","commonAssumption":"\"If I can''t donate organs, I can''t donate anything.\"","reality":"Tissue donation eligibility is broader than organ donation. It can occur irrespective of the manner of death, and even after the body has been moved to a mortuary.","verdict":"rarely-absolute"},{"id":"corneas","factor":"Corneas","commonAssumption":"\"My eyesight is terrible, so my corneas are no use.\"","reality":"South African tissue banks give roughly 6 to 65 years, and up to 70 in some cases. Poor eyesight and cataracts do not disqualify a donor. Corneas can be recovered after either a natural or an unnatural death, but the window is short — around 12 hours. Previous laser eye surgery, tuberculosis, lymphoma and leukaemia are contraindications.","verdict":"stated-criteria"},{"id":"skin-and-bone","factor":"Skin and bone","commonAssumption":"\"Surely there''s an age limit.\"","reality":"South African tissue banks give roughly 15 or 16 up to 80 years, for donors without cancer, septicaemia, hepatitis or HIV. The recovery window is longer than for corneas — bone up to about five days after death.","verdict":"stated-criteria"},{"id":"heart-valves","factor":"Heart valves","commonAssumption":"\"Only adults can donate heart valves.\"","reality":"Valve criteria are narrower than for bone or skin, and they are set by the tissue bank rather than by law — published South African criteria group heart valves with bone and skin, and paediatric valves are used where they are available. Treat any specific age range you are given as that bank’s, and check it with them rather than quoting it from a course.","verdict":"stated-criteria"},{"id":"organ-specific","factor":"Organ-by-organ assessment","commonAssumption":"\"It''s all or nothing — either you can donate everything or nothing.\"","reality":"It is not all or nothing. Extended criteria donors may be eligible where individual organs are assessed as transplantable, so being unsuitable for one donation does not mean being unsuitable for all.","verdict":"depends"}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'who-is-a-potential-donor', 'who-can-donate', 2, 'Who becomes a potential donor', 'PRIMARY',
  NULL, 'ComparePanel',
  '{"intro":"Eligibility depends partly on the route to donation. The same person can be eligible by one route and not another.","columns":[{"id":"dbd","label":"After brain death","emphasis":true},{"id":"dcd","label":"After circulatory death"},{"id":"living","label":"Living donation"},{"id":"tissue","label":"Tissue donation"}],"rows":[{"id":"who","label":"Who may be considered","cells":{"dbd":"Any patient declared brain dead — irreversible structural brain damage with total loss of brainstem function — on a mechanical ventilator.","dcd":"Patients in palliative care settings where treatment is withdrawn and death is imminent.","living":"Someone making a conscious decision to donate, who is assessed as fit to do so.","tissue":"Far wider. Eligibility does not depend on the manner of death, and donation is possible even after transfer to a mortuary."}},{"id":"typical-cause","label":"Typical route there","cells":{"dbd":"Traumatic head injury, stroke, or cerebral hypoxia from drowning or drug overdose.","dcd":"A decision to withdraw life-sustaining treatment, where death is expected to follow.","living":"A planned decision, often to help a relative.","tissue":"Any manner of death."}},{"id":"age","label":"Age","cells":{"dbd":"No age restriction for solid organ donation.","dcd":"No age restriction for solid organ donation.","living":"Assessed as part of the donor work-up.","tissue":"Stated ranges apply, set by the tissue bank rather than by law: corneas generally 6–65 (up to 70 in some cases); skin and bone roughly 15 or 16 to 80. Heart valve limits differ between banks — ask them rather than quoting a range."}},{"id":"comorbidities","label":"Comorbidities","cells":{"dbd":"Extended criteria donors with hypertension, diabetes or HIV may still be eligible if individual organs are assessed as transplantable.","dcd":"Assessed individually, as above.","living":"Assessed thoroughly before any donation proceeds.","tissue":"Skin and bone donors are typically without infectious disease or cancer."}}],"bottomLine":"Different routes have different requirements, and none of them can be assessed in advance by a member of the public — or by the potential donor themselves."}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'takeaways', 'who-can-donate', 3, 'Key takeaways', 'TAKEAWAYS',
  NULL, 'TakeawayList',
  '{"takeaways":[{"id":"t1","text":"There is no age restriction for solid organ donation."},{"id":"t2","text":"Extended criteria donors with hypertension, diabetes or HIV may still be eligible if individual organs are assessed as transplantable."},{"id":"t3","text":"Tissue donation is broader than organ donation: irrespective of the manner of death, and possible even after the body has been moved to a mortuary."},{"id":"t4","text":"Tissue does have stated ranges, set by the bank rather than by law — corneas generally 6–65, skin and bone roughly 15 or 16 to 80. Heart valve limits vary between banks."},{"id":"t5","text":"Poor eyesight and cataracts do not disqualify a cornea donor."},{"id":"t6","text":"Self-exclusion is a real and invisible loss point. Do not rule anyone out on their behalf, and do not overcorrect by claiming a condition is irrelevant."},{"id":"t7","text":"Nobody should be excluded from being offered the option to donate."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
