insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'study-guide', 'who-can-donate', 5, 'Study guide', 'STUDY_GUIDE',
  NULL, NULL,
  '{"summary":"Objective 5 of the Save7 study guide: know when someone is eligible for organ donation.","sections":[{"id":"s1","heading":"Who is a potential organ donor","body":"Any patient who is declared brain dead — irreversible structural brain damage with total loss of brainstem function — is a potential organ donor. Common causes of eligibility through brain death include traumatic head injuries, strokes, and cerebral hypoxia from drowning or drug overdose."},{"id":"s2","heading":"By route","bullets":["Donation after brain death (DBD) — a patient on a mechanical ventilator declared brain dead by two doctors","Donation after circulatory death (DCD) — possible in palliative care settings where treatment is withdrawn and death is imminent","Living donation — a conscious decision to donate a kidney or a liver segment","Tissue donation — irrespective of the manner of death, and even after transfer to a mortuary"]},{"id":"s3","heading":"Age and comorbidities","bullets":["There is no age restriction for solid organ donation","Extended criteria donors with comorbidities such as hypertension, diabetes or HIV may still be eligible if individual organs are assessed as transplantable"]},{"id":"s4","heading":"Tissue-specific criteria","bullets":["Cornea donors are generally between 6 and 65 years old; poor eyesight and cataracts do not disqualify them","Skin and bone donors are typically healthy individuals between 16 and 80, without infectious diseases or cancer","Heart valve donors are eligible from 6 months up to 55 years"]}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

