insert into learn_modules (
  slug, level_slug, position, title, number, core_question, intro_markdown,
  est_minutes, is_mandatory
) values (
  'transplant-landscape', 'advanced', 1, 'The Transplant Landscape', 10,
  'How are transplant candidates actually selected and assessed?', 'This is the most clinical module in the course, and it is here rather than in Beginner for a reason: nobody needs it to start a conversation.

**One distinction before you begin.** Everything up to now has been about who can *give*. This module is about who can *receive*. Donor eligibility and recipient candidacy are different questions with different criteria, and conflating them is one of the easiest mistakes to make in public.', 20,
  true
) on conflict (slug) do update set
  level_slug = excluded.level_slug, position = excluded.position,
  title = excluded.title, number = excluded.number,
  core_question = excluded.core_question, intro_markdown = excluded.intro_markdown,
  est_minutes = excluded.est_minutes, is_mandatory = excluded.is_mandatory,
  updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'intro', 'transplant-landscape', 0, 'Why this matters', 'INTRO',
  'Candidate selection is genuinely hard, genuinely contested, and genuinely changing. Mancini and Lietz put it plainly: *patients with comorbidities who in the past would not be suitable transplantation candidates are now often considered for transplantation.*

That is worth understanding for its own sake, and it is also the strongest possible reason to avoid stating exclusion rules with confidence in public.

It is also worth knowing what transplantation achieves at the top end. One-year survival after cardiac transplantation approaches **90%**, and half of recipients survive more than **11 years**. Those numbers are why the shortage matters.', NULL,
  NULL
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'heart-transplantation', 'transplant-landscape', 1, 'Heart transplantation', 'PRIMARY',
  NULL, 'EligibilityMatrix',
  '{"intro":"Heart transplant candidacy, as an in-depth example of how recipient assessment works. Note how few factors are truly absolute — and remember these are criteria for *receiving* a heart, not for donating one.","bottomLine":"Most contraindications to heart transplantation are relative, not absolute, and have shifted as evidence has changed. Candidate selection is a specialist multidisciplinary judgement — which is exactly why an advocate should not attempt it.","factors":[{"id":"indications","factor":"Who is considered","commonAssumption":"\"A transplant is offered whenever the heart is failing.\"","reality":"Heart failure is progressive, and only a minority reach the point where transplantation is considered — around 5% to 10% of heart failure patients have advanced, stage D disease. In the most advanced phase, transplantation has been the only means of improving both quality of life and survival.","verdict":"depends"},{"id":"life-expectancy","factor":"Other systemic illness","commonAssumption":"\"Any other serious illness rules you out.\"","reality":"An absolute contraindication is a systemic illness with a life expectancy under two years *despite* a transplant — the question is whether the transplant would actually change the outcome.","verdict":"depends"},{"id":"malignancy","factor":"Cancer history","commonAssumption":"\"Any history of cancer is an absolute bar.\"","reality":"There is no five-year rule in current guidance. The 2024 ISHLT guideline recommends individualised risk stratification with oncology, and supports transplantation where malignancy-related survival will not affect post-transplant survival and recurrence risk is low given tumour type, response to therapy and a negative metastatic evaluation.","verdict":"depends","verifiedAgainst":"ISHLT Guidelines for the Evaluation and Care of Cardiac Transplant Candidates, 2024, read directly"},{"id":"hiv","factor":"HIV","commonAssumption":"\"HIV is an absolute contraindication.\"","reality":"HIV is not the contraindication. *Uncontrolled* HIV is. The 2024 ISHLT guideline advises against transplantation where there is opportunistic infection or HIV-related malignancy, no stable antiretroviral regimen, a detectable viral load, or a low CD4 count — and considers candidates with an undetectable viral load and a CD4 count above 200. A criterion far narrower than the public assumption, and worth stating precisely rather than reassuringly.","verdict":"rarely-absolute","verifiedAgainst":"ISHLT Guidelines for the Evaluation and Care of Cardiac Transplant Candidates, 2024, read directly"},{"id":"renal","factor":"Renal dysfunction","commonAssumption":"\"Kidney problems make a heart transplant impossible.\"","reality":"Irreversible renal dysfunction is an absolute contraindication only for patients being considered for a heart transplant alone. Creatinine above 2.5 mg/dL, or creatinine clearance below 25 mL/min, is listed among the relative contraindications.","verdict":"depends"},{"id":"obesity","factor":"Body mass index","commonAssumption":"\"Weight is an automatic exclusion.\"","reality":"Both obesity and cachexia are weighed, not decisive. Older guidance published cut-offs (BMI above 35, below 18); the 2024 guideline treats body mass as one comorbidity assessed alongside the others, which is why an advocate should name the factor and never the number.","verdict":"rarely-absolute"},{"id":"pulmonary","factor":"Lung function","commonAssumption":"\"Only the heart matters for a heart transplant.\"","reality":"Significant obstructive pulmonary disease and fixed pulmonary hypertension appear among the absolute contraindications; severe pulmonary dysfunction with FEV1 below 40% of normal is relative. The rest of the body has to be able to support the new heart.","verdict":"depends"},{"id":"substance-use","factor":"Smoking, alcohol and drug use","commonAssumption":"\"They just won''t give organs to people who smoke.\"","reality":"Drug, tobacco or alcohol abuse within six months is a relative contraindication — a window, not a permanent bar. Psychosocial stability is assessed for the same reason: a transplant requires lifelong medication adherence.","verdict":"rarely-absolute"},{"id":"mcs","factor":"Mechanical circulatory support","commonAssumption":"\"It''s transplant or nothing.\"","reality":"Mechanical circulatory support means transplantation is not always the only option in advanced heart failure. It can bridge a patient toward transplantation, or serve as a destination therapy in its own right.","verdict":"depends"}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'other-solid-organs', 'transplant-landscape', 2, 'Lung, kidney, liver and pancreas', 'PRIMARY',
  NULL, 'ComparePanel',
  '{"intro":"How recipient candidacy differs across organs. The lung column draws on the ISHLT consensus document, which is unusually direct about age.","columns":[{"id":"lung","label":"Lung","emphasis":true},{"id":"kidney","label":"Kidney"},{"id":"liver","label":"Liver"},{"id":"pancreas","label":"Pancreas"}],"rows":[{"id":"indications","label":"Main indications","cells":{"lung":"Advanced lung disease such as COPD or cystic fibrosis, with a risk of death exceeding 50% over two years.","kidney":"End-stage renal disease (CKD 5).","liver":"Hepatocellular carcinoma, decompensated cirrhosis, fulminant hepatic failure.","pancreas":"Diabetes no longer manageable with insulin, often alongside kidney failure."}},{"id":"age","label":"Age","cells":{"lung":"No upper age limit is endorsed as an absolute contraindication, and age alone is not one. The 2021 ISHLT consensus treats age as a risk factor rather than a threshold: the categorical “over 65 with low reserve” rule belongs to the 2006 and 2014 versions. Candidates over 65 are now more than 30% of the United States waiting list and the age group with the highest transplant rate, though survival falls beyond about 70.","kidney":"Assessed as part of overall candidacy.","liver":"Assessed as part of overall candidacy.","pancreas":"Assessed as part of overall candidacy."},"verifiedAgainst":"Leard LE, et al. Consensus document for the selection of lung transplant candidates: an update from the ISHLT. J Heart Lung Transplant 2021;40(11):1349-1379, read directly"},{"id":"malignancy","label":"Cancer history","cells":{"lung":"Malignancy with a high risk of recurrence or death is an absolute contraindication, and every candidate has age-appropriate and disease-specific cancer screening with confirmation that there is no residual or metastatic disease. Note what current guidance does *not* say: the fixed “two years clear, five to be safe” intervals come from the superseded 2014 document, and the 2021 update assesses recurrence risk individually instead.","kidney":"Assessed individually.","liver":"Hepatocellular carcinoma can itself be an indication, within defined limits — the Milan criteria: one lesion up to 5 cm, or up to three each up to 3 cm, with no macrovascular invasion.","pancreas":"Assessed individually."},"verifiedAgainst":"Leard LE, et al. ISHLT consensus for the selection of lung transplant candidates. J Heart Lung Transplant 2021;40(11):1349-1379, read directly (malignancy with high recurrence risk absolute; fixed disease-free intervals dropped); ISHLT Guidelines for the Evaluation and Care of Cardiac Transplant Candidates 2024 (individualised risk stratification with oncology, no fixed interval); Milan criteria for hepatocellular carcinoma"},{"id":"obesity","label":"Body mass index","cells":{"lung":"Class I obesity (BMI 30.0–34.9), particularly truncal, is a relative contraindication.","kidney":"Assessed individually.","liver":"Assessed individually.","pancreas":"Assessed individually."}},{"id":"living-donation","label":"Living donation possible?","cells":{"lung":"Not in routine South African practice.","kidney":"Yes — the most common form of living donation.","liver":"Yes — a liver segment.","pancreas":"No."}}],"bottomLine":"Age by itself is not a contraindication to transplantation. What matters is physiological reserve and the comorbidities that tend to accompany age — which is why these decisions are made by teams, at the time, and not by rules of thumb."}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'takeaways', 'transplant-landscape', 3, 'Key takeaways', 'TAKEAWAYS',
  NULL, 'TakeawayList',
  '{"takeaways":[{"id":"t1","text":"Donor eligibility and recipient candidacy are different questions. This module is about who receives."},{"id":"t2","text":"Most contraindications are relative rather than absolute, and several have moved as evidence has moved."},{"id":"t3","text":"Age by itself is not considered a contraindication to transplantation — it is physiological reserve and accompanying comorbidities that matter."},{"id":"t4","text":"Public assumptions are often far broader than the actual criterion. HIV is not a bar to a heart transplant; uncontrolled HIV is — the 2024 guideline looks for a stable antiretroviral regimen, an undetectable viral load and a CD4 count above 200."},{"id":"t5","text":"Mechanical circulatory support means transplantation is not always the only option in advanced heart failure."},{"id":"t6","text":"Outcomes are good: one-year survival after cardiac transplantation approaches 90%, and half of recipients survive beyond 11 years."},{"id":"t7","text":"You are not expected to reproduce any of this in public. Understanding its shape is enough — and it is the reason to avoid confident exclusion claims."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

