insert into learn_modules (
  slug, level_slug, position, title, number, core_question, intro_markdown,
  est_minutes, is_mandatory
) values (
  'life-after-donation', 'advanced', 2, 'Life After Donation', 11,
  'What happens to the recipient after the transplant?', 'Public conversation about donation tends to stop at the operating theatre, as though transplantation were an ending.

For the recipient it is a beginning. Understanding what follows — the medication, the monitoring, the possibility of complications years later — makes you a more honest advocate, and it makes the gift you are describing more real.', 16,
  true
) on conflict (slug) do update set
  level_slug = excluded.level_slug, position = excluded.position,
  title = excluded.title, number = excluded.number,
  core_question = excluded.core_question, intro_markdown = excluded.intro_markdown,
  est_minutes = excluded.est_minutes, is_mandatory = excluded.is_mandatory,
  updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'intro', 'life-after-donation', 0, 'Why this matters', 'INTRO',
  'Overselling transplantation does the cause no favours. A transplant is not a cure and it is not a return to how things were before; it trades one serious medical situation for another, usually far better, one.

Saying that plainly is more persuasive than a happy ending, and it respects recipients'' actual experience. It also means you will not be caught out — because a learner who has been told transplantation is a cure will eventually meet someone whose experience says otherwise.

The honest version is still a good story: one-year survival after a heart transplant approaches 90%, and half of recipients live beyond eleven years. Those years come with daily medication and regular monitoring.', NULL,
  NULL
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'the-recipient-journey', 'life-after-donation', 1, 'The recipient''s journey', 'PRIMARY',
  NULL, 'PathwayJourney',
  '{"intro":"What follows a transplant, over days, months and years.","showLossPoints":false,"steps":[{"id":"transplantation","label":"The transplant operation","summary":"Major surgery, with a recovery period to match.","detail":"The operation itself is the part everyone pictures, and clinically it is the most predictable stage of the whole journey."},{"id":"immunosuppression","label":"Immunosuppression","summary":"Lifelong medication, with real trade-offs.","detail":"The recipient''s immune system will recognise the transplanted organ as foreign. Immunosuppressive medication prevents it from rejecting the graft — and by design leaves the recipient more vulnerable to infection.\n\nThis is the central trade of transplantation: a functioning organ in exchange for a managed, lifelong compromise of the immune system. Advances in immunosuppression are a large part of why survival figures have improved so much."},{"id":"rejection","label":"Rejection","summary":"Monitored for, and often treatable.","detail":"Rejection is why follow-up is lifelong rather than a courtesy. It is monitored for deliberately, and an episode of rejection does not automatically mean the graft is lost — it means treatment changes."},{"id":"early-complications","label":"Early complications","summary":"The first weeks and months.","detail":"Surgical and infectious complications are concentrated early, when immunosuppression is heaviest and the surgery is fresh."},{"id":"late-complications","label":"Late complications","summary":"Months and years later — the part nobody expects.","detail":"Complications do not stop once a recipient goes home. In liver transplantation, **biliary strictures and incisional hernias are the most common late surgical complications**.\n\nThe detail shows how ongoing this care is. Anastomotic biliary strictures can usually be managed endoscopically and rarely need surgery. A biliary stricture requires the hepatic artery to be checked, because the two are connected. Ischaemic-type intrahepatic strictures are a common reason for re-transplantation. And recipients of living-related grafts, or grafts donated after circulatory death, are at the highest risk of late biliary and vascular complications."},{"id":"graft-survival","label":"Long-term graft survival","summary":"Grafts last a long time. They do not last forever.","detail":"Survival varies by organ and by person. For hearts, half of recipients survive beyond eleven years. Some recipients will eventually need a second transplant — which is one reason the donor shortage compounds over time."},{"id":"follow-up","label":"Lifelong follow-up","summary":"Why the medical relationship never really ends.","detail":"Medication adherence, monitoring for rejection, and watching for late complications continue indefinitely. This is also why psychosocial stability appears in candidate selection: a transplant asks a great deal of the person who receives it."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'takeaways', 'life-after-donation', 2, 'Key takeaways', 'TAKEAWAYS',
  NULL, 'TakeawayList',
  '{"takeaways":[{"id":"t1","text":"Transplantation is the start of a lifelong medical journey, not a cure."},{"id":"t2","text":"Immunosuppression prevents rejection and increases vulnerability to infection. It is a trade, not a fix."},{"id":"t3","text":"Rejection is monitored for and often treatable. An episode does not automatically mean losing the graft."},{"id":"t4","text":"Complications can appear years later. In liver transplantation, biliary strictures and incisional hernias are the most common late surgical complications."},{"id":"t5","text":"Recipients of living-related or circulatory-death grafts carry the highest risk of late biliary and vascular complications."},{"id":"t6","text":"Grafts do not last forever, and some recipients need a second transplant — so the shortage compounds."},{"id":"t7","text":"Describe transplantation honestly. Overselling it damages credibility and misrepresents recipients'' lives."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

