insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'study-guide', 'life-after-donation', 4, 'Study guide', 'STUDY_GUIDE',
  NULL, NULL,
  '{"summary":"What follows a transplant.","sections":[{"id":"s1","heading":"Immunosuppression and rejection","body":"Immunosuppressive medication prevents the recipient''s immune system from rejecting the graft, at the cost of increased vulnerability to infection. It continues for life. Rejection is monitored for, and an episode does not automatically mean the graft is lost."},{"id":"s2","heading":"Late complications after liver transplantation","bullets":["Biliary strictures and incisional hernias are the most common late surgical complications","Anastomotic biliary strictures are amenable to endoscopic intervention and rarely require surgery","The presence of a biliary stricture mandates evaluation of hepatic artery patency","Ischaemic-type intrahepatic strictures are a common indication for re-transplantation","Recipients of living-related liver transplants and of grafts donated after circulatory death are at highest risk of late biliary and vascular complications"],"verifiedAgainst":"Reviewed 23 August 2026 against established hepatology and transplant-surgery practice: biliary stricture as the commonest late surgical complication, endoscopic management of anastomotic strictures, arterial patency assessment when a stricture is found, ischaemic-type intrahepatic strictures as a re-transplant indication, and the higher biliary and vascular risk of living-donor and DCD grafts. No figure or threshold is asserted."},{"id":"s3","heading":"Graft survival","body":"Varies by organ and by individual. One-year survival after cardiac transplantation approaches 90%, with half of recipients surviving beyond eleven years. Some recipients will require re-transplantation."},{"id":"s4","heading":"Why this matters to an advocate","body":"Describing transplantation accurately — including its costs — is more persuasive than presenting it as a cure, and it respects the actual experience of recipients."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
