insert into learn_modules (
  slug, level_slug, position, title, number, core_question, intro_markdown,
  est_minutes, is_mandatory
) values (
  'art-of-the-conversation', 'advanced', 3, 'The Art of the Conversation', 12,
  'How do I handle the hardest conversations, with people in real distress?', 'Module 4 taught you to talk to a friend over coffee. This module is about the conversations that are genuinely difficult: grief, family disagreement, deep mistrust, and beliefs you do not share.

These are the conversations where good intentions are not enough, and where an advocate can do real harm.', 20,
  true
) on conflict (slug) do update set
  level_slug = excluded.level_slug, position = excluded.position,
  title = excluded.title, number = excluded.number,
  core_question = excluded.core_question, intro_markdown = excluded.intro_markdown,
  est_minutes = excluded.est_minutes, is_mandatory = excluded.is_mandatory,
  updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'intro', 'art-of-the-conversation', 0, 'Five things that hold under pressure', 'INTRO',
  'Two rules carry most of the weight here.

**You are not a counsellor.** Recognising when a conversation has moved beyond your role — and stopping — is a skill, not a failure.

**You are never obliged to win.** Someone in acute grief who feels respected by you may reconsider months later. Someone who feels pressured will not.

Beyond that, five principles come directly out of the source material rather than out of intuition:

1. **Decouple.** The death and the donation are separate conversations. A family must understand and accept a death before donation is raised — and it is raised by a coordinator, not by whoever delivered the news.
2. **Do not rush.** In a single-centre study of 107 brain-dead potential donors, families who took 48 hours or more to decide consented at 73% (11 of 15), against 55% (51 of 92) among those who decided sooner — the authors’ conclusion being that a delayed decision was *not inferior*, not that delay improves consent. The delayed group is small, and the study is not South African. Read it for what it supports: delay is not refusal, and patience costs nothing.
3. **Patience and empathy are the method, not the garnish.** Accepting a diagnosis of death by neurological criteria genuinely takes time, and the guidelines make room for it — that is what *accommodation* means.
4. **Do not assume.** It should never be assumed that because someone comes from a particular ethnic, cultural or spiritual background, donation should not be raised. That assumption removes their choice before it is offered.
5. **The conversation has value either way.** Discussing donation as part of end-of-life care helps families independent of what they decide. You are not only recruiting donors.

> **Where these come from.** The next lesson walks through **FACTS** — the Family Approach to Consent for Transplant Strategy used by transplant coordinators in South Africa. Its published account names planning, interpreters, facilitating the family''s own discussion and a donor pause; the staged walkthrough there is Save7''s way of teaching that reasoning, not the strategy''s own protocol. Several of the principles above are visible in it. Note carefully: FACTS is a clinical strategy for procurement coordinators, and this course teaches you to *understand* it, not to perform it.', NULL,
  NULL
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'hard-conversations', 'art-of-the-conversation', 1, 'Five hard conversations', 'PRIMARY',
  NULL, 'ScenarioDialogue',
  '{"intro":"None of these has a clean answer. Choose the response you think does least harm and most good, then read why.","scenarios":[{"id":"s1","speaker":"A family at the bedside","quote":"She''s still warm. Her heart is beating. You''re asking us to give up on her.","whatsReallyHappening":"The family is being asked to accept something that contradicts what they can see and touch. This is the hardest moment in the entire donation pathway.","reflectPrompt":"What should you absolutely not do here?","options":[{"id":"o1","text":"Explain that brain death is legally and medically death, and that the ventilator is what is keeping her heart beating.","quality":"poor","feedback":"The facts are right and the timing is wrong. A family in this moment cannot absorb a clinical explanation, and leading with one reads as correcting their grief. This explanation belongs to the clinical team."},{"id":"o2","text":"\"I can''t imagine how impossible this feels. Nobody is asking you to give up on her.\" Then stop talking, and let them lead.","quality":"strong","feedback":"Correct. It acknowledges the reality of what they are experiencing, gently rejects the framing of ''giving up'', and then makes space. Silence is a legitimate and often the best contribution here."},{"id":"o3","text":"Ask whether they would like to talk to the doctors again, or have someone from their faith community with them.","quality":"strong","feedback":"Excellent, and it maps onto how this is actually done: the consultant and coordinator may involve a faith representative or hospital chaplain precisely to support families here. You are connecting them to the right people rather than substituting for them."},{"id":"o4","text":"Point out gently that she would want to help others if she could.","quality":"poor","feedback":"This puts words in the patient''s mouth at the family''s most vulnerable moment. It will be experienced as pressure, and it can permanently damage trust in everyone present."}],"debrief":"This is a clinical and counselling conversation, not an advocacy one. It is also why decoupling exists: the family must be allowed to absorb the death before donation is raised at all, and support is deliberately not withdrawn immediately. The guidelines even have a name for the time this takes — accommodation."},{"id":"s2","speaker":"Two siblings, disagreeing in front of you","quote":"He never said anything about this. — He did, he told me years ago. — Well he never told me.","whatsReallyHappening":"A family with no shared knowledge of the person''s wishes. The disagreement is often about far more than donation.","reflectPrompt":"Whose side are you on?","options":[{"id":"o1","text":"Support the sibling who says he wanted to donate — they have the relevant information.","quality":"poor","feedback":"Taking a side inside a grieving family is not your role, and it will fracture the conversation entirely."},{"id":"o2","text":"\"It sounds like this is something you need to work out together, and there''s no rush from me. Would it help to have someone from the team explain the options to you both at the same time?\"","quality":"strong","feedback":"Refuses to arbitrate, removes time pressure you have no business applying, and offers a shared source of information so both siblings hear the same thing. The evidence supports the patience: taking longer did not reduce consent."},{"id":"o3","text":"Explain who is legally entitled to consent, so they know where they stand.","quality":"workable","feedback":"The legal position is real — consent comes from next of kin: spouse, parent, child, brother or sister. But delivered by an advocate in a live family dispute it reads as picking a winner. This is better coming from the coordinator."},{"id":"o4","text":"Suggest they think about what he would have wanted.","quality":"workable","feedback":"Reasonable in principle, and it is exactly the question they are already fighting about. It rarely resolves anything in the moment."}],"debrief":"This scenario is the clearest possible argument for Save7''s whole premise. The disagreement exists because a conversation never happened — and because consent from next of kin is always required, that missing conversation is now doing real damage."},{"id":"s3","speaker":"A community member","quote":"People like us don''t get organs. We only give them.","whatsReallyHappening":"A statement about structural inequity and mistrust of the health system. It may well be grounded in real experience, and dismissing it would be both wrong and counterproductive.","reflectPrompt":"What makes this different from a factual misconception?","options":[{"id":"o1","text":"Reassure them that allocation is based on medical criteria, not on who you are.","quality":"workable","feedback":"It may be accurate, but offered as a first response it sounds like a denial of their experience. Trust has to come before information."},{"id":"o2","text":"\"That''s a fair thing to be suspicious about, and I''m not going to tell you your experience is wrong. Can I ask what you''ve seen that makes you say that?\"","quality":"strong","feedback":"Takes the concern seriously as a legitimate position rather than an error to be fixed, and listens before responding. This is the only route to a real conversation here."},{"id":"o3","text":"Acknowledge that equity of access is a real problem in South African healthcare, and be honest about it, while explaining how allocation itself is meant to work.","quality":"strong","feedback":"Honest on both counts — and it happens to align with how the professional guidance frames it: equity of access to donation support pathways is described as a crucial component of healthcare delivery. Conceding a real problem is what makes the rest of what you say believable."},{"id":"o4","text":"Point out that they might need a transplant themselves one day.","quality":"poor","feedback":"Self-interest framing on top of an equity concern will land as manipulative, and it sidesteps what they actually said."}],"debrief":"Mistrust grounded in real inequity is not a myth and cannot be corrected like one. Worth knowing: donation is possible from all communities and cultures in South Africa, and it should never be assumed that someone''s background means the subject shouldn''t be raised — the assumption itself is part of the inequity."},{"id":"s4","speaker":"An older relative","quote":"My body needs to be whole when it''s buried. That''s not negotiable for me.","whatsReallyHappening":"A religious or cultural conviction about bodily integrity. This is a settled belief, not an information gap.","reflectPrompt":"What outcome should you be aiming for here?","options":[{"id":"o1","text":"Explain that recovery is done surgically and the body is restored to its original state, so burial is not usually affected.","quality":"workable","feedback":"The fact is correct and genuinely reassuring to many people — the body is restored afterwards. But offered unprompted against a stated conviction, it reads as an attempt to talk them out of it. Offer it if they ask."},{"id":"o2","text":"\"I hear you, and I''m not going to try to change that. Thank you for telling me clearly.\"","quality":"strong","feedback":"Accepting a settled position gracefully is a legitimate and successful outcome. It also keeps the relationship intact for every future conversation."},{"id":"o3","text":"Accept their position, and ask whether they''ve told the rest of the family so nobody has to guess on their behalf.","quality":"strong","feedback":"The best available answer. It fully respects their decision and still achieves Save7''s actual goal — a family that knows. Since consent comes from next of kin, a clearly communicated ''no'' prevents an agonising guess later."},{"id":"o4","text":"Ask whether tissue donation might be more acceptable than organ donation.","quality":"poor","feedback":"Negotiating around a stated conviction about bodily integrity. It signals that you did not accept their answer the first time."}],"debrief":"A clearly communicated refusal is a good outcome for Save7. The failure mode is not ''no'' — it is a family left guessing. And there is evidence the conversation itself helps families regardless of the decision they reach."},{"id":"s5","speaker":"Someone at a Save7 event","quote":"So how many organs actually get transplanted in South Africa each year? What''s the real number?","whatsReallyHappening":"A direct factual question where a confident guess would be tempting — and where the honest answer requires you to know how old your figures are.","reflectPrompt":"What is the professional answer?","options":[{"id":"o1","text":"Give your best recollection of the figure, with a caveat that you''re not certain.","quality":"poor","feedback":"A half-remembered statistic becomes the thing they repeat to other people. The caveat does not travel with it."},{"id":"o2","text":"Give the figures you know with their date attached — \"between 2010 and 2019 there were 2 416 kidney transplants and 292 heart transplants\" — and offer to get the current numbers from the Organ Donor Foundation.","quality":"strong","feedback":"This is the professional answer. You have given real figures, dated them honestly so nobody mistakes a decade total for last year, and pointed to the body that maintains the current numbers."},{"id":"o3","text":"Redirect to the point that the number is far lower than the need, without quoting a figure.","quality":"workable","feedback":"Honest and usable, and it answers the underlying point. Better still if you follow up with dated figures."},{"id":"o4","text":"Explain that statistics vary by source and year, so a single number is misleading.","quality":"workable","feedback":"True, but it can sound evasive. Pair it with the dated figures you do have."}],"debrief":"Advocates are trusted because they are careful. Always date a statistic. The figures in this course are decade totals for 2010–2019 from the Organ Donor Foundation — useful, and not the same thing as current annual numbers."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'understanding-the-donation-conversation', 'art-of-the-conversation', 2, 'Understanding the donation conversation', 'PRIMARY',
  NULL, 'PathwayJourney',
  '{"intro":"When a family in South Africa is asked about donation, the conversation usually follows a structured process called **FACTS** — the Family Approach to Consent for Transplant Strategy, developed at Wits Transplant and adapted from the UK''s NHS Blood and Transplant model.\n\n**Read this before you go any further.** FACTS is a clinical strategy for transplant procurement coordinators. Completing this course does not qualify you to approach a family or to request consent, and this lesson is not training to do either. You are here to understand *why* the professional conversation is built this way — because the reasoning behind it also makes you better at the conversations that genuinely are yours to have.\n\nWalk through the stages below. They are Save7’s teaching sequence, built from the elements the published account of FACTS describes rather than a reproduction of the strategy itself. For each one, note the principle underneath it.","steps":[{"id":"f1","label":"Planning","summary":"Before anyone speaks to the family, the approach is prepared.","detail":"Who should be in the room. When. Where. In which language. What the family already knows. None of this is left to the moment.\n\n**The principle:** the conversations that go worst are the ones nobody thought about first. Setting, timing and language are not details — they are most of the outcome."},{"id":"f2","label":"Breaking bad news","summary":"The family is told, and helped to understand, that the person has died.","detail":"This step is about the death and nothing else. Donation is not mentioned. A family that has not yet grasped that their person has died cannot meaningfully consider anything else.\n\n**The principle:** this is decoupling, and it is the reason it matters. It is not a technique for improving consent rates — it is what makes a decision a real decision."},{"id":"f3","label":"Time-out break","summary":"The family is deliberately left alone.","detail":"A pause is built into the process. Not an accident, not a gap while staff are busy elsewhere — a designed interval before donation is raised at all.\n\n**The principle:** silence and space are part of the method. If a formal clinical strategy schedules them, you can stop treating a pause in your own conversation as a failure to fill."},{"id":"f4","label":"Assessing understanding and acceptance of loss","summary":"Before donation is raised, someone checks what the family actually understands.","detail":"Not whether they were told. What they understood, and whether they accept it. Families sitting beside a warm body with a beating heart very often have not — and that is not stubbornness, it is the situation contradicting the information.\n\n**The principle:** never assume that being told is the same as understanding. Check, gently, before you build on anything."},{"id":"f5","label":"The consent conversation","summary":"Donation is introduced. Concerns are heard, questions answered.","detail":"Only now. The coordinator raises donation, then mostly listens — surfacing concerns, answering what is asked, giving accurate information in a supportive way. It is not a pitch.\n\n**The principle:** listening comes before informing, and information is offered rather than pushed. This is the step most people imagine the whole conversation to be, and it is one of eight."},{"id":"f6","label":"Time-out break","summary":"A second deliberate pause, so the family can talk among themselves.","detail":"The family is left to discuss it without a professional present. A decision that has to be made in front of the person asking for it is not a free one.\n\n**The principle:** people need to process without an audience. Do not stand there waiting for an answer."},{"id":"f7","label":"Final family discussion","summary":"The coordinator returns, asks for the decision, and respects it.","detail":"Remaining concerns are addressed and the family''s decision is taken as final. A no is accepted as an answer, not treated as an opening position.\n\n**The principle:** you are never obliged to win. A family who felt respected while declining is a better outcome than one who felt worked on."},{"id":"f8","label":"Family follow-up, feedback and support","summary":"Support continues after the decision, whatever it was.","detail":"Follow-up after recovery, ongoing support, and where appropriate information about what happened to the donated organs.\n\n**The principle:** the family is not a means to an organ. The relationship does not end when the answer is given — which is also the difference between advocacy and recruitment."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'takeaways', 'art-of-the-conversation', 3, 'Key takeaways', 'TAKEAWAYS',
  NULL, 'TakeawayList',
  '{"takeaways":[{"id":"t1","text":"You are not a counsellor. Knowing when to stop and refer is a skill, not a failure."},{"id":"t2","text":"Decouple. The death and the donation are separate conversations, and the second is not yours to start at the bedside."},{"id":"t3","text":"Do not rush a family. Taking longer than 48 hours was associated with higher consent, not lower."},{"id":"t4","text":"A clearly communicated ''no'' is a good outcome. A family left guessing is the failure."},{"id":"t5","text":"Mistrust grounded in real inequity is not a myth and cannot be corrected like one."},{"id":"t6","text":"Never put words in a dead or dying person''s mouth, and never negotiate around a stated conviction."},{"id":"t7","text":"Always date a statistic. \"2 416 kidney transplants between 2010 and 2019\" is useful; \"about 2 400 a year\" is wrong."},{"id":"t8","text":"Silence is a legitimate contribution. Sometimes it is the best one."},{"id":"t9","text":"FACTS is a coordinator''s strategy, not a volunteer''s script. Understanding why it is built that way is the point; performing it is not your role — and the stages taught here are Save7''s way of explaining it, not the strategy''s own protocol."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

