insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'intro', 'become-a-save7-advocate', 0, 'Where you started, and where you are now', 'INTRO',
  'At the beginning of this course, the goal was stated plainly: to leave feeling *I understand organ donation and transplantation well enough to confidently start a conversation about it.*

You now know who is waiting, and that one donor can save seven lives and improve up to fifty more. You know where donations are lost, and that most of those losses are human rather than medical. You can explain that death is the irreversible loss of the capacity for consciousness and the capacity to breathe — and why the heart can still be beating. You know that two independent doctors certify brain death and neither may be on the transplant team. You know the statute is Chapter 8 of the National Health Act, that consent comes from next of kin, and that the family bears no costs. You know there is no age restriction for solid organ donation.

And you have practised the conversation itself — including the versions of it that go badly.', NULL,
  NULL
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'what-you-can-now-do', 'become-a-save7-advocate', 1, 'What you can now do', 'TAKEAWAYS',
  NULL, 'TakeawayList',
  '{"takeaways":[{"id":"t1","text":"Explain why people need donated organs and tissues, without medical jargon."},{"id":"t2","text":"Describe the South African donation pathway, and name the points where it breaks down."},{"id":"t3","text":"Explain brain death clearly, accurately and kindly — and distinguish it from a coma."},{"id":"t4","text":"Name who is involved in a donation, and which roles exist as safeguards."},{"id":"t5","text":"Answer the common legal questions: the Act, consent, unnatural deaths, and costs."},{"id":"t6","text":"Correct the six commonest myths without making anyone feel foolish."},{"id":"t7","text":"Avoid ruling anyone out — and know where firm criteria genuinely do exist."},{"id":"t8","text":"Describe life after transplantation honestly, including what it costs the recipient."},{"id":"t9","text":"Handle a hard conversation, and recognise when it is not yours to have."},{"id":"t10","text":"Date every statistic you quote."},{"id":"t11","text":"Encourage the people you love to tell each other what they want."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'the-call-to-action', 'become-a-save7-advocate', 2, 'Start the conversation', 'PRIMARY',
  'There is one thing left to do, and it is not a Save7 campaign.

**Talk to your own family.** Tonight, if you can. Not a presentation — a sentence. *I''ve been doing a course on organ donation, and I want you to know what I''d want.*

That is the whole thing. Every module in this course exists to make that sentence possible — and it matters because **consent from next of kin is always required**. Without that conversation, the people who love you are left guessing at the worst moment of their lives.

> Whether it is for awareness campaigns or a private conversation with family and friends, the most important part is simply starting the conversation.

One decision can save seven lives. Yours starts with a conversation.', NULL,
  NULL
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

