insert into learn_lessons (
  slug, module_slug, position, title, kind, body_markdown, component_key, payload
) values (
  'study-guide', 'become-a-save7-advocate', 4, 'Study guide', 'STUDY_GUIDE',
  NULL, NULL,
  '{"summary":"A single page to keep. Save7 may wish to produce a designed version of this as an advocate reference card.","sections":[{"id":"s1","heading":"The ten questions this course answered","bullets":["Who needs organs?","Why are organs being lost?","What is brain death?","How does donation work?","Who is involved?","What does South African law say?","Who can donate?","What happens after transplantation?","How do I talk about donation?","How can I become part of the solution?"]},{"id":"s2","heading":"The facts worth memorising","bullets":["One donor can save seven lives through organ donation, and improve up to fifty more through tissue and corneas — the figures the ODF and ORTIDA publish","Consent from next of kin is always required","Two registered doctors certify brain death; neither may be on the transplant team; one must have five years'' HPCSA registration","Death is the irreversible loss of the capacity for consciousness and the capacity to breathe","There is no age restriction for solid organ donation","The body is restored to its original state after recovery, and anaesthesia is given during it","The family bears no costs once death is declared and consent obtained","The governing statute is Chapter 8 of the National Health Act No. 61 of 2003"]},{"id":"s3","heading":"The Save7 position","body":"Whether it is for awareness campaigns or a private conversation with family and friends, the most important part is simply starting the conversation."}]}'::jsonb
) on conflict (module_slug, slug) do update set
  position = excluded.position,
  title = excluded.title, kind = excluded.kind,
  body_markdown = excluded.body_markdown, component_key = excluded.component_key,
  payload = excluded.payload, updated_at = now();

