  false, 'Annals of Transplantation, 22, 17–23 (2017). DOI: 10.12659/AOT.901616', 'Han, S. Y., Kim, J. I., Lee, E.-W., Jang, H.-Y., Han, K. H., Oh, S. W., & Roh, Y.-N.', NULL,
