insert into learn_review_items (
  entity_type, entity_ref, location, claim, category, severity, status, source_hint, notes
) values (
  'LESSON', 'advanced/the-law/legal-framework#steps[4]', 'M9 · The Law › The legal framework', 'Can a family override a donor?',
  'LEGAL', 1, 'APPROVED',
  'Checked against the National Health Act 61 of 2003 as gazetted, plus Regulation 9 of GN R180 (2 March 2012) as described in the peer-reviewed literature. Still needs a qualified legal review against the current consolidated text and the gazetted regulations.', 'Checked against: National Health Act s 62(1)-(2), read from a consolidated text: relatives may donate only in the absence of a donation by the person or a contrary direction given while alive. The gap between that and hospital practice — families are approached in every case and a refusal is respected — is documented in South African legal scholarship (Slabbert & Venter, ''Autonomy in organ donations v family consent: A South African legislative context'', De Jure, 2019) and in the transplant literature.'
) on conflict (entity_type, entity_ref, claim) do update set
