insert into learn_review_items (
  entity_type, entity_ref, location, claim, category, severity, status, source_hint, notes
) values (
  'LESSON', 'advanced/the-law/legal-framework#steps[7]', 'M9 · The Law › The legal framework', 'Costs',
  'LEGAL', 1, 'APPROVED',
  'Checked against the National Health Act 61 of 2003 as gazetted, plus Regulation 9 of GN R180 (2 March 2012) as described in the peer-reviewed literature. Still needs a qualified legal review against the current consolidated text and the gazetted regulations.', 'Checked against: Checked to conclusion: the National Health Act (consolidated) and the gazetted regulations GN R180 of 2 March 2012 were both searched, and neither allocates the costs of donation. The Act''s only money provisions are s 60 (payment for tissue; reimbursement of a donor''s reasonable expenses) and the regulations'' equivalents. The practice statement is the Organ Donor Foundation''s, quoted from its FAQs: the donor and their family incur no costs because the hospital or tissue bank covers the medical expenses of the donation from the moment consent is given.'
